import { useState } from 'react'
import { Link, useNavigate } from 'react-router-dom'

const previewCells = [
  { palace: '巽四', star: '天辅', door: '杜门', god: '九天' },
  { palace: '离九', star: '天英', door: '景门', god: '值符' },
  { palace: '坤二', star: '天芮', door: '死门', god: '螣蛇' },
  { palace: '震三', star: '天冲', door: '伤门', god: '六合' },
  { palace: '中五', star: '一念', door: '起局', god: '太阴' },
  { palace: '兑七', star: '天柱', door: '惊门', god: '白虎' },
  { palace: '艮八', star: '天任', door: '生门', god: '玄武' },
  { palace: '坎一', star: '天蓬', door: '休门', god: '九地' },
  { palace: '乾六', star: '天心', door: '开门', god: '太常' },
]

const notes = [
  ['择时', '以当前时刻或指定年月日时起局。'],
  ['看宫', '星、门、神、天地盘干分层追读。'],
  ['复盘', '记录验证窗口，以现实反馈校准判断。'],
]

const trustPoints = ['可信排盘', '知识回链', '本地复盘']

function LightHome() {
  const [question, setQuestion] = useState('')
  const navigate = useNavigate()

  const handleSubmit = (event) => {
    event.preventDefault()
    const trimmed = question.trim()
    navigate(trimmed ? `/divination?question=${encodeURIComponent(trimmed)}` : '/divination')
  }

  return (
    <div className="relative overflow-hidden bg-[#101513] text-[#f3efe4]">
      <div className="pointer-events-none absolute inset-0">
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_8%,rgba(197,164,94,0.16),transparent_28%),radial-gradient(circle_at_72%_44%,rgba(52,102,86,0.18),transparent_34%),linear-gradient(180deg,#101513_0%,#12100d_100%)]" />
        <div className="absolute inset-0 opacity-[0.08] [background-image:linear-gradient(90deg,#d8b56d_1px,transparent_1px),linear-gradient(180deg,#d8b56d_1px,transparent_1px)] [background-size:72px_72px]" />
      </div>

      <section className="relative px-4 py-6 md:py-10">
        <div className="mx-auto grid max-w-6xl items-center gap-6 lg:grid-cols-[0.94fr_1.06fr]">
          <div className="max-w-xl">
            <p className="text-sm tracking-[0.22em] text-[#bfa46b]">时家奇门 · 择时起局 · 九宫读象</p>
            <h1
              className="mt-4 text-4xl font-semibold leading-tight text-[#f7f0df] md:text-6xl"
              style={{ fontFamily: "'Noto Serif SC', 'SimSun', 'STSong', serif", textWrap: 'balance' }}
            >
              奇门遁甲在线排盘
            </h1>
            <p className="mt-4 max-w-[58ch] text-base leading-7 text-[#c9c0ad] md:text-lg md:leading-8">
              以当前时间或指定时间起局，查看九宫盘、星门神和宫位依据；每一次判断都保留为可复盘的观察记录。
            </p>

            <form onSubmit={handleSubmit} className="mt-5 max-w-xl border border-[#8f7442] bg-[#171b17]/88 p-3 shadow-[0_18px_50px_rgba(0,0,0,0.22)]">
              <label htmlFor="home-question" className="sr-only">此刻所问何事</label>
              <div className="flex flex-col gap-3 sm:flex-row">
                <input
                  id="home-question"
                  value={question}
                  onChange={(event) => setQuestion(event.target.value)}
                  maxLength={120}
                  placeholder="此刻所问何事？一盘只问一件事。"
                  className="min-h-12 flex-1 border border-[#3a4038] bg-[#0e1210] px-4 text-sm text-[#f7f0df] placeholder:text-[#8f8879] focus:border-[#c6a15a] focus:outline-none focus:ring-2 focus:ring-[#c6a15a]/20"
                />
                <button
                  type="submit"
                  className="min-h-12 border border-[#c6a15a] bg-[#c6a15a] px-6 text-sm font-semibold text-[#15130f] transition-colors hover:bg-[#d6b66d] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#f7f0df]"
                >
                  进入排盘
                </button>
              </div>
            </form>

            <div className="mt-3 flex flex-wrap gap-2">
              {trustPoints.map((item) => (
                <span key={item} className="border border-[#6d5d36] bg-[#121814]/80 px-3 py-1 text-xs text-[#b8ad98]">
                  {item}
                </span>
              ))}
            </div>

            <div className="mt-3 flex flex-wrap items-center gap-x-5 gap-y-2 text-sm text-[#9f9584]">
              <Link to="/knowledge" className="transition-colors hover:text-[#d6b66d]">先看基础知识</Link>
              <Link to="/about" className="transition-colors hover:text-[#d6b66d]">查看免责声明</Link>
            </div>
          </div>

          <div className="relative mx-auto w-full max-w-[260px] sm:max-w-[420px] lg:max-w-[520px]">
            <div className="absolute -inset-6 bg-[radial-gradient(circle,rgba(198,161,90,0.16),transparent_58%)] blur-2xl" />
            <div className="relative grid aspect-square grid-cols-3 border border-[#9f7e45]/55 bg-[#111511]/88 shadow-[0_22px_70px_rgba(0,0,0,0.38)]">
              {previewCells.map((cell, index) => (
                <div
                  key={cell.palace}
                  className={`group min-h-16 border-[#806537]/45 p-2 transition-colors hover:bg-[#1a211c] md:min-h-24 md:p-5 ${index % 3 !== 2 ? 'border-r' : ''} ${index < 6 ? 'border-b' : ''} ${cell.palace === '中五' ? 'bg-[#1d1a12]' : ''}`}
                >
                  <div className="flex items-center justify-between gap-2 text-xs text-[#9f9584]">
                    <span>{cell.palace}</span>
                    <span>{cell.god}</span>
                  </div>
                  <div className="mt-2 text-lg font-semibold text-[#f1ead7] md:mt-5 md:text-2xl" style={{ fontFamily: "'Noto Serif SC', 'SimSun', 'STSong', serif" }}>
                    {cell.star}
                  </div>
                  <div className="mt-2 text-sm text-[#c6a15a]">{cell.door}</div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </section>

      <section className="relative border-t border-[#302a1d] bg-[#f3efe4] px-4 py-10 text-[#211b15]">
        <div className="mx-auto grid max-w-6xl gap-6 md:grid-cols-[0.8fr_1.2fr] md:items-start">
          <div>
            <h2 className="text-2xl font-semibold" style={{ fontFamily: "'Noto Serif SC', 'SimSun', 'STSong', serif" }}>不是替你决定，而是帮你复盘</h2>
            <p className="mt-3 max-w-[54ch] text-sm leading-7 text-[#5b4f40]">
              排盘页默认按当前时间生成盘局。你可以改时间、补充所问事项，再点击宫位查看依据、风险和观察点。
            </p>
          </div>
          <div className="grid gap-3 sm:grid-cols-3">
            {notes.map(([title, text]) => (
              <div key={title} className="border-t border-[#9c865b] pt-3">
                <div className="font-semibold text-[#6b241f]">{title}</div>
                <p className="mt-2 text-sm leading-6 text-[#5b4f40]">{text}</p>
              </div>
            ))}
          </div>
        </div>
      </section>
    </div>
  )
}



const jadeHomepage = "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>奇门遁甲 · 玄枢协议 / 墨玉</title>\n<link rel=\"stylesheet\" href=\"https://miaoda.feishu.cn/fonts/css2?family=Noto+Serif+SC:wght@400;600;700;900&family=Noto+Sans+SC:wght@300;400;500;700&display=swap\">\n<style>\n:root{\n  --bg:#081311;\n  --bg2:#0d1a17;\n  --panel:rgba(13,18,16,.72);\n  --cyan:#a3c9bb;\n  --cyan-dim:rgba(163,201,187,.45);\n  --magenta:#c9a06a;\n  --violet:#8a98a0;\n  --lime:#a9b79a;\n  --text:#dce4de;\n  --dim:#78877f;\n  --mono:ui-monospace,\"SF Mono\",\"JetBrains Mono\",Menlo,Consolas,monospace;\n  --serif:\"Noto Serif SC\",\"Songti SC\",serif;\n  --sans:\"Noto Sans SC\",\"PingFang SC\",sans-serif;\n}\n*{margin:0;padding:0;box-sizing:border-box}\nhtml{scroll-behavior:smooth}\nbody{\n  background:var(--bg);color:var(--text);font-family:var(--sans);font-weight:300;\n  line-height:1.8;overflow-x:hidden;-webkit-font-smoothing:antialiased;\n  background-image:\n    radial-gradient(circle at 22% 8%,rgba(138,152,160,.16),transparent 45%),\n    radial-gradient(circle at 82% 30%,rgba(201,160,106,.10),transparent 42%),\n    radial-gradient(circle at 50% 90%,rgba(163,201,187,.08),transparent 50%);\n  background-attachment:fixed;\n}\n::selection{background:var(--magenta);color:#fff}\n\n/* 扫描线 / 噪点 */\n.scanlines{\n  position:fixed;inset:0;z-index:2;pointer-events:none;opacity:.11;\n  background:repeating-linear-gradient(0deg,rgba(255,255,255,.10) 0 1px,transparent 1px 3px);\n  mix-blend-mode:overlay;\n}\n.noise{\n  position:fixed;inset:0;z-index:3;pointer-events:none;opacity:.07;\n  background-image:url(\"data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='3' stitchTiles='stitch'/><feColorMatrix type='saturate' values='0'/></filter><rect width='160' height='160' filter='n' opacity='0.5'/></svg>\");\n}\n.vignette{position:fixed;inset:0;z-index:4;pointer-events:none;background:radial-gradient(ellipse at 50% 40%,transparent 45%,rgba(0,0,0,.55) 100%)}\n\n.wrap{max-width:1300px;margin:0 auto;padding:0 44px;position:relative;z-index:6}\n\n/* ===== 导航 ===== */\nheader{\n  position:fixed;top:0;left:0;right:0;z-index:30;\n  border-bottom:1px solid rgba(163,201,187,.14);\n  transition:background .4s,box-shadow .4s;\n}\nheader.scrolled{background:rgba(6,11,10,.86);backdrop-filter:blur(16px);box-shadow:0 0 40px rgba(163,201,187,.08)}\n.nav{display:flex;align-items:center;justify-content:space-between;height:76px}\n.brand{display:flex;align-items:center;gap:14px;text-decoration:none;color:var(--text)}\n.mark{\n  width:40px;height:40px;position:relative;display:grid;place-items:center;\n  border:1px solid var(--cyan);color:var(--cyan);font-family:var(--mono);font-size:11px;\n  box-shadow:0 0 14px rgba(163,201,187,.35),inset 0 0 14px rgba(163,201,187,.18);\n  clip-path:polygon(0 0,100% 0,100% 70%,70% 100%,0 100%);\n}\n.brand-txt{font-family:var(--serif);font-size:17px;letter-spacing:5px;color:#eaf2ec;font-weight:600}\n.brand-sub{font-family:var(--mono);font-size:9px;letter-spacing:2.5px;color:var(--cyan);opacity:.8;margin-top:2px}\n.nav-links{display:flex;gap:34px;list-style:none}\n.nav-links a{\n  font-family:var(--mono);font-size:11px;letter-spacing:2px;color:var(--dim);text-decoration:none;\n  position:relative;padding:6px 2px;transition:color .3s,text-shadow .3s;\n}\n.nav-links a:hover,.nav-links a.active{color:var(--cyan);text-shadow:0 0 12px rgba(163,201,187,.6)}\n.nav-links a.active::after{content:\"\";position:absolute;left:0;right:0;bottom:-2px;height:1px;background:var(--cyan);box-shadow:0 0 8px var(--cyan)}\n.btn{\n  display:inline-flex;align-items:center;gap:10px;padding:11px 24px;cursor:pointer;\n  font-family:var(--mono);font-size:12px;letter-spacing:2px;text-decoration:none;\n  color:var(--cyan);border:1px solid var(--cyan);background:rgba(163,201,187,.05);\n  clip-path:polygon(0 0,calc(100% - 12px) 0,100% 12px,100% 100%,12px 100%,0 calc(100% - 12px));\n  transition:all .3s;\n}\n.btn:hover{background:rgba(163,201,187,.16);box-shadow:0 0 24px rgba(163,201,187,.35);color:#fff}\n.btn.hot{color:#14100a;background:linear-gradient(100deg,var(--magenta),#d9bc8e);border-color:transparent;font-weight:700;box-shadow:0 0 28px rgba(201,160,106,.45)}\n.btn.hot:hover{color:#14100a;box-shadow:0 0 40px rgba(201,160,106,.7)}\n\n/* ===== 首屏 ===== */\n.hero{position:relative;min-height:100svh;display:flex;align-items:center;padding:130px 0 60px;overflow:hidden}\n.hero::before{\n  content:\"\";position:absolute;inset:0;z-index:1;\n  background-image:linear-gradient(rgba(163,201,187,.09) 1px,transparent 1px),linear-gradient(90deg,rgba(163,201,187,.09) 1px,transparent 1px);\n  background-size:150px 150px;\n  mask-image:radial-gradient(ellipse at 62% 45%,#000 0%,transparent 70%);\n  -webkit-mask-image:radial-gradient(ellipse at 62% 45%,#000 0%,transparent 70%);\n  transform:perspective(600px) rotateX(52deg) scale(1.6);\n  transform-origin:50% 80%;opacity:.35;\n}\n.hero-inner{display:grid;grid-template-columns:1fr 1.05fr;gap:40px;align-items:center;width:100%}\n.hero-inner>*{min-width:0}\n.eyebrow{\n  font-family:var(--mono);font-size:11px;letter-spacing:4px;color:var(--cyan);\n  display:flex;align-items:center;gap:12px;margin-bottom:28px;\n}\n.eyebrow .dot{width:6px;height:6px;background:var(--magenta);box-shadow:0 0 10px var(--magenta);animation:blink 1.6s steps(2) infinite}\n@keyframes blink{50%{opacity:.25}}\nh1{\n  position:relative;font-family:var(--serif);font-weight:900;\n  font-size:clamp(56px,7vw,100px);line-height:1.06;letter-spacing:14px;color:#f1f5f1;\n  text-shadow:0 0 30px rgba(163,201,187,.28),0 0 80px rgba(138,152,160,.2);\n}\nh1 em{font-style:normal;color:var(--cyan)}\nh1::before,h1::after{\n  content:attr(data-text);position:absolute;inset:0;opacity:0;pointer-events:none;\n}\nh1::before{color:var(--magenta);left:2px;text-shadow:-2px 0 var(--magenta)}\nh1::after{color:var(--cyan);left:-2px;text-shadow:2px 0 var(--cyan)}\nh1:hover::before{opacity:.30;animation:glitch-a .5s steps(2) infinite}\nh1:hover::after{opacity:.30;animation:glitch-b .5s steps(2) infinite}\n@keyframes glitch-a{0%{clip-path:inset(0 0 72% 0)}25%{clip-path:inset(40% 0 30% 0)}50%{clip-path:inset(80% 0 4% 0)}75%{clip-path:inset(20% 0 60% 0)}100%{clip-path:inset(0 0 0 0)}}\n@keyframes glitch-b{0%{clip-path:inset(60% 0 10% 0)}25%{clip-path:inset(10% 0 78% 0)}50%{clip-path:inset(30% 0 45% 0)}75%{clip-path:inset(70% 0 8% 0)}100%{clip-path:inset(0 0 0 0)}}\n.hero-sub{\n  font-family:var(--mono);font-size:13px;letter-spacing:6px;color:#beddd2;margin-top:16px;\n}\n.hero-sub span{color:var(--magenta)}\n.hero-desc{max-width:470px;margin-top:26px;color:#94a39b;font-size:14px;line-height:2;letter-spacing:.4px}\n.hero-desc b{color:var(--cyan);font-weight:500}\n.hero-actions{display:flex;gap:14px;margin-top:40px;flex-wrap:wrap}\n.hero-stats{display:flex;gap:38px;margin-top:50px;flex-wrap:wrap}\n.stat{border-left:1px solid rgba(163,201,187,.35);padding-left:14px}\n.stat b{display:block;font-family:var(--mono);font-size:22px;color:#eaf2ec;letter-spacing:1px;line-height:1.3;text-shadow:0 0 14px rgba(163,201,187,.45)}\n.stat i{font-style:normal;font-family:var(--mono);font-size:9px;color:var(--dim);letter-spacing:2px}\n\n/* 仪器 */\n.instrument{position:relative;display:grid;place-items:center;padding:10px;min-width:0}\n.instrument svg{width:min(600px,100%);overflow:visible;filter:drop-shadow(0 0 24px rgba(163,201,187,.12))}\n.instrument::after{\n  content:\"\";position:absolute;inset:12%;border-radius:50%;pointer-events:none;\n  background:radial-gradient(circle,rgba(163,201,187,.10),transparent 62%);\n}\n.hud{\n  position:absolute;font-family:var(--mono);font-size:9px;letter-spacing:1.5px;color:var(--cyan);\n  border:1px solid rgba(163,201,187,.30);background:rgba(6,12,10,.8);padding:5px 9px;\n  white-space:nowrap;backdrop-filter:blur(4px);\n}\n.hud.m{border-color:rgba(201,160,106,.4);color:#d8bb8c}\n.hud i{font-style:normal;display:block;font-size:8px;color:var(--dim);letter-spacing:1px}\n.hud.tl{left:-2%;top:2%}\n.hud.tr{right:-2%;top:-1%}\n.hud.bl{left:-1%;bottom:3%}\n.hud.br{right:-2%;bottom:7%}\n.hud::before{content:\"\";position:absolute;left:-10px;top:50%;width:9px;height:1px;background:rgba(163,201,187,.5)}\n.hud.tr::before,.hud.br::before{left:auto;right:-10px}\n\n/* 状态条 */\n.status{\n  border-top:1px solid rgba(163,201,187,.18);border-bottom:1px solid rgba(163,201,187,.18);\n  background:linear-gradient(90deg,rgba(163,201,187,.06),transparent 60%);\n  overflow:hidden;white-space:nowrap;font-family:var(--mono);font-size:11px;letter-spacing:2px;\n}\n.status-track{display:flex;gap:52px;padding:15px 0;color:#8ca096;animation:slide 38s linear infinite;width:max-content}\n.status b{color:var(--cyan);font-weight:500}\n.status em{color:var(--magenta);font-style:normal}\n@keyframes slide{from{transform:translateX(0)}to{transform:translateX(-50%)}}\n\n/* ===== 通用 ===== */\nsection{position:relative;z-index:6}\n.sec{padding:104px 0}\n.sec-head{margin-bottom:54px;display:flex;align-items:flex-end;justify-content:space-between;gap:40px;flex-wrap:wrap}\n.kicker{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:var(--magenta);display:flex;align-items:center;gap:10px;margin-bottom:18px}\n.kicker::before{content:\"//\";color:var(--cyan)}\n.sec-title{font-family:var(--serif);font-size:clamp(26px,3.3vw,40px);font-weight:700;letter-spacing:4px;line-height:1.45;color:#eff4f0}\n.sec-title span{color:var(--cyan);text-shadow:0 0 24px rgba(163,201,187,.35)}\n.sec-note{max-width:340px;font-family:var(--mono);font-size:10px;line-height:2;letter-spacing:1.5px;color:var(--dim);text-align:right;border-right:1px solid rgba(163,201,187,.25);padding-right:16px}\n\n/* 模块卡 */\n.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\n.card{\n  position:relative;padding:34px 26px 30px;background:var(--panel);border:1px solid rgba(163,201,187,.18);\n  transition:border-color .35s,transform .35s,box-shadow .35s;overflow:hidden;\n}\n.card::before,.card::after{content:\"\";position:absolute;width:14px;height:14px;border:1px solid var(--cyan);transition:all .35s}\n.card::before{left:-1px;top:-1px;border-right:0;border-bottom:0}\n.card::after{right:-1px;bottom:-1px;border-left:0;border-top:0}\n.card:hover{border-color:rgba(163,201,187,.6);transform:translateY(-4px);box-shadow:0 14px 40px rgba(0,0,0,.5),0 0 30px rgba(163,201,187,.12)}\n.card:hover::before,.card:hover::after{width:26px;height:26px;box-shadow:0 0 10px rgba(163,201,187,.5)}\n.card .idx{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:var(--magenta);margin-bottom:26px;display:block}\n.card h4{font-family:var(--serif);font-size:18px;letter-spacing:3px;color:#e6eee8;font-weight:600;margin-bottom:12px}\n.card p{font-size:12.5px;color:#86948c;line-height:1.95;min-height:72px}\n.card .meter{margin-top:22px;display:flex;align-items:center;gap:10px;font-family:var(--mono);font-size:9px;color:var(--dim);letter-spacing:1px}\n.card .meter .bar{flex:1;height:2px;background:rgba(163,201,187,.14);position:relative}\n.card .meter .bar::after{content:\"\";position:absolute;left:0;top:0;height:100%;width:var(--v,80%);background:linear-gradient(90deg,var(--cyan),var(--magenta));box-shadow:0 0 8px rgba(163,201,187,.6)}\n\n/* 九宫 HUD */\n.hud-grid{display:grid;grid-template-columns:1.02fr .98fr;gap:34px;align-items:stretch}\n.board{\n  position:relative;display:grid;grid-template-columns:repeat(3,1fr);gap:1px;\n  background:rgba(163,201,187,.18);border:1px solid rgba(163,201,187,.28);padding:1px;\n  box-shadow:0 0 40px rgba(163,201,187,.08),inset 0 0 60px rgba(163,201,187,.04);\n}\n.hcell{\n  position:relative;background:rgba(9,13,12,.94);aspect-ratio:1/.78;padding:10px;\n  display:flex;flex-direction:column;justify-content:space-between;min-width:0;overflow:hidden;\n}\n.hcell::after{\n  content:\"\";position:absolute;inset:0;pointer-events:none;\n  background:linear-gradient(180deg,rgba(163,201,187,.10),transparent 40%);\n  opacity:0;transition:opacity .3s;\n}\n.hcell:hover::after{opacity:1}\n.hcell .t{display:flex;justify-content:space-between;font-family:var(--mono);font-size:8.5px;color:#5e7268;letter-spacing:1px}\n.hcell .t b{color:var(--magenta);font-weight:400}\n.hcell .c{font-family:var(--serif);font-size:24px;color:#ddece3;text-align:center;line-height:1.2;text-shadow:0 0 16px rgba(163,201,187,.35)}\n.hcell .c small{display:block;font-family:var(--mono);font-size:8px;letter-spacing:1.5px;color:var(--cyan);margin-top:3px}\n.hcell .b{display:flex;justify-content:space-between;font-family:var(--mono);font-size:8px;color:#5e7268}\n.hcell.center{background:radial-gradient(circle at 50% 50%,rgba(163,201,187,.22),rgba(9,13,12,.95) 62%)}\n.hcell.center .c{font-size:30px;color:#fff}\n.hcell.lit{background:linear-gradient(180deg,rgba(201,160,106,.12),rgba(9,13,12,.95))}\n.hcell.lit .c{color:#efe0c8}\n\n/* 终端 */\n.terminal{\n  background:rgba(4,9,8,.9);border:1px solid rgba(163,201,187,.24);display:flex;flex-direction:column;\n  box-shadow:0 0 30px rgba(0,0,0,.6),inset 0 0 50px rgba(163,201,187,.04);\n}\n.term-bar{display:flex;align-items:center;gap:8px;padding:9px 12px;border-bottom:1px solid rgba(163,201,187,.18);font-family:var(--mono);font-size:9px;color:var(--dim);letter-spacing:1px}\n.term-bar span{width:7px;height:7px;border-radius:50%;background:#33453f}\n.term-bar span:first-child{background:var(--magenta);box-shadow:0 0 8px var(--magenta)}\n.term-bar span:nth-child(2){background:var(--cyan);box-shadow:0 0 8px var(--cyan)}\n.term-bar em{font-style:normal;margin-left:6px;color:#7f9288}\n.term-body{padding:20px 18px;font-family:var(--mono);font-size:11.5px;line-height:2.05;color:#8fa199;flex:1;overflow:hidden}\n.term-body .p{color:var(--cyan)}\n.term-body .k{color:#dce4de}\n.term-body .g{color:var(--lime)}\n.term-body .m{color:var(--magenta)}\n.cursor{display:inline-block;width:7px;height:13px;background:var(--cyan);vertical-align:-1px;animation:blink 1.1s steps(2) infinite;box-shadow:0 0 8px var(--cyan)}\n.term-foot{border-top:1px solid rgba(163,201,187,.14);padding:10px 14px;display:flex;justify-content:space-between;font-family:var(--mono);font-size:9px;color:#5e7268;letter-spacing:1px}\n\n/* 日志 */\n.logs{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\n.log{\n  display:block;text-decoration:none;color:inherit;padding:26px 24px 22px;background:rgba(10,15,13,.6);\n  border:1px solid rgba(163,201,187,.16);position:relative;transition:all .35s;\n}\n.log:hover{border-color:rgba(201,160,106,.55);background:rgba(201,160,106,.04);box-shadow:0 0 32px rgba(201,160,106,.1)}\n.log .tag{font-family:var(--mono);font-size:9px;letter-spacing:1.5px;color:var(--magenta);margin-bottom:16px;display:flex;justify-content:space-between}\n.log .tag em{font-style:normal;color:#5e7268}\n.log h4{font-family:var(--serif);font-size:17px;line-height:1.6;letter-spacing:1.5px;color:#e4ede7;font-weight:600;margin-bottom:12px}\n.log p{font-size:12px;color:#86948c;line-height:1.9}\n.log .foot{margin-top:18px;font-family:var(--mono);font-size:9px;color:var(--cyan);letter-spacing:1px;opacity:.7}\n\n/* CTA */\n.cta{padding:120px 0 110px;text-align:center;position:relative;border-top:1px solid rgba(163,201,187,.18);overflow:hidden}\n.cta .ring{\n  position:absolute;left:50%;top:50%;width:min(900px,110vw);aspect-ratio:1;transform:translate(-50%,-50%);\n  border:1px solid rgba(163,201,187,.12);border-radius:50%;\n  box-shadow:0 0 80px rgba(163,201,187,.06) inset;\n}\n.cta .ring::before,.cta .ring::after{content:\"\";position:absolute;inset:12%;border:1px solid rgba(201,160,106,.14);border-radius:50%}\n.cta .ring::after{inset:26%;border-color:rgba(163,201,187,.15)}\n.cta-inner{position:relative;z-index:7}\n.cta h2{font-family:var(--serif);font-size:clamp(30px,4.2vw,54px);letter-spacing:9px;font-weight:700;color:#f1f5f1;line-height:1.5;text-shadow:0 0 40px rgba(163,201,187,.25)}\n.cta h2 span{color:var(--cyan)}\n.cta p{max-width:520px;margin:22px auto 38px;font-family:var(--mono);font-size:11px;letter-spacing:2px;line-height:2;color:#78877f}\n.cta .btn{padding:15px 40px;font-size:13px}\n\nfooter{border-top:1px solid rgba(163,201,187,.14);padding:34px 0;position:relative;z-index:7;font-family:var(--mono);font-size:9px;letter-spacing:1.5px;color:#54635c}\n.foot{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}\n.foot .ok{color:var(--lime)}\n.foot .ok::before{content:\"●\";margin-right:6px;font-size:8px}\n\n.reveal{opacity:0;transform:translateY(24px);transition:opacity .9s ease,transform .9s ease}\n.reveal.in{opacity:1;transform:none}\n\n@media (max-width:1080px){\n  .hero-inner{grid-template-columns:1fr;gap:30px}\n  .hero{padding-top:118px}\n  .instrument{order:-1;margin-top:10px}\n  .instrument svg{width:min(520px,86vw)}\n  .hud.tl,.hud.tr{top:8%}\n  .hud.tl{left:0}\n  .hud.tr{top:18%}\n  .cards{grid-template-columns:repeat(2,1fr)}\n  .hud-grid{grid-template-columns:1fr}\n  .logs{grid-template-columns:1fr}\n  .nav-links{display:none}\n  .sec-note{text-align:left;border-right:0;border-left:1px solid rgba(163,201,187,.25);padding:0 0 0 14px}\n}\n@media (max-width:640px){\n  .wrap{padding:0 18px}\n  .sec{padding:76px 0}\n  h1{font-size:48px;letter-spacing:7px}\n  .hero-sub{letter-spacing:3px;font-size:11px}\n  .hero-desc{font-size:13px}\n  .hero-actions .btn{flex:1;justify-content:center}\n  .hero-stats{gap:20px}\n  .stat b{font-size:18px}\n  .cards{grid-template-columns:1fr}\n  .card p{min-height:auto}\n  .instrument svg{width:100%}\n  .hud{font-size:8px;padding:4px 6px}\n  .hud.bl{left:0}\n  .hud.tl,.hud.br{display:none}\n  .hud.br{bottom:18%}\n  .board{padding:1px}\n  .hcell .c{font-size:18px}\n  .hcell .t{font-size:7.5px}\n  .hcell .b{font-size:7px}\n  .brand-txt{font-size:15px;letter-spacing:3px}\n  .nav{height:64px}\n  .mark{width:34px;height:34px}\n  .term-body{font-size:10.5px;padding:16px 12px}\n  .status{font-size:10px}\n  .sec-head{margin-bottom:38px}\n}\n@media (prefers-reduced-motion:reduce){\n  .sweep,.ring-a,.ring-b,.ring-c,.status-track,.dot{animation:none!important}\n}\n\n/* ==== 素雅校准 ==== */\nh1{text-shadow:0 0 26px rgba(163,201,187,.14),0 0 70px rgba(138,152,160,.10)}\n.instrument svg{filter:drop-shadow(0 0 18px rgba(163,201,187,.08))}\n.btn.hot{background:rgba(201,160,106,.10);border:1px solid rgba(201,160,106,.65);color:#e6d3b1;font-weight:500;box-shadow:0 0 16px rgba(201,160,106,.10)}\n.btn.hot:hover{background:rgba(201,160,106,.18);color:#f4e7cf;box-shadow:0 0 26px rgba(201,160,106,.18)}\n</style>\n</head>\n<body>\n<div class=\"scanlines\"></div>\n<div class=\"noise\"></div>\n<div class=\"vignette\"></div>\n\n<header id=\"hdr\">\n  <div class=\"wrap nav\">\n    <a class=\"brand\" href=\"#top\">\n      <span class=\"mark\">遁甲</span>\n      <span>\n        <span class=\"brand-txt\">玄枢</span>\n        <div class=\"brand-sub\">QIMEN PROTOCOL / 墨玉</div>\n      </span>\n    </a>\n    <ul class=\"nav-links\">\n      <li><a href=\"#top\" class=\"active\">BOOT</a></li>\n      <li><a href=\"#engine\">ENGINE</a></li>\n      <li><a href=\"#board\">MATRIX</a></li>\n      <li><a href=\"/knowledge\" target=\"_top\">知识库</a></li><li><a href=\"/cases\" target=\"_top\">案例</a></li>\n    </ul>\n    <a class=\"btn hot\" href=\"/divination\" target=\"_top\">接 入 盘 面</a>\n  </div>\n</header>\n\n<!-- ===== 首屏 ===== -->\n<section class=\"hero\" id=\"top\">\n  <div class=\"wrap hero-inner\">\n    <div class=\"hero-copy\">\n      <div class=\"eyebrow\"><span class=\"dot\"></span> SYSTEM ONLINE · 时家奇门 · 转盘</div>\n      <h1 data-text=\"奇门遁甲\">奇门<em>遁甲</em></h1>\n      <div class=\"hero-sub\">CELESTIAL COMPASS <span>/</span> QIMEN DUNJIA</div>\n      <p class=\"hero-desc\">\n        罗盘定方，星盘定时。以<b>节气</b>为时钟，以<b>九宫</b>为矩阵，把三奇六仪、八门九星写入一张可计算的盘面。\n      </p>\n      <div class=\"hero-actions\">\n        <a class=\"btn hot\" href=\"/divination\" target=\"_top\">启动排盘 <span>→</span></a>\n        <a class=\"btn\" href=\"#engine\">查看引擎</a>\n      </div>\n      <div class=\"hero-stats\">\n        <div class=\"stat\"><b>360°</b><i>罗盘刻度</i></div>\n        <div class=\"stat\"><b>24</b><i>山向定位</i></div>\n        <div class=\"stat\"><b>9+8+8</b><i>星门神层</i></div>\n      </div>\n    </div>\n\n    <div class=\"instrument reveal\">\n      <div class=\"hud tl\"><i>LOC</i>31.23°N 121.47°E</div>\n      <div class=\"hud tr m\"><i>JU</i>阳遁三局</div>\n      <div class=\"hud bl\"><i>SHI</i>值使 · 杜门</div>\n      <div class=\"hud br\"><i>FU</i>值符 · 天辅</div>\n\n      <svg id=\"compass\" viewBox=\"-300 -300 600 600\" role=\"img\" aria-label=\"奇门遁甲罗盘与星盘仪\">\n        <defs>\n          <radialGradient id=\"core\" cx=\"50%\" cy=\"50%\" r=\"50%\">\n            <stop offset=\"0%\" stop-color=\"#ffffff\" stop-opacity=\".95\"/>\n            <stop offset=\"35%\" stop-color=\"#a3c9bb\" stop-opacity=\".55\"/>\n            <stop offset=\"100%\" stop-color=\"#a3c9bb\" stop-opacity=\"0\"/>\n          </radialGradient>\n          <linearGradient id=\"sweepGrad\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n            <stop offset=\"0%\" stop-color=\"#a3c9bb\" stop-opacity=\"0\"/>\n            <stop offset=\"100%\" stop-color=\"#a3c9bb\" stop-opacity=\".55\"/>\n          </linearGradient>\n        </defs>\n\n        <!-- 外层刻度 -->\n        <g id=\"ticks\" stroke=\"#a3c9bb\" opacity=\".55\"></g>\n        <g id=\"degrees\" font-family=\"ui-monospace,monospace\" font-size=\"9\" fill=\"#4e6e62\"></g>\n\n        <!-- 二十四山 -->\n        <circle r=\"252\" fill=\"none\" stroke=\"#a3c9bb\" stroke-opacity=\".28\"/>\n        <g id=\"shan\" font-family=\"'Noto Serif SC',serif\" font-size=\"13\" fill=\"#a8d2c6\"></g>\n\n        <!-- 八卦 -->\n        <circle r=\"219\" fill=\"none\" stroke=\"#c9a06a\" stroke-opacity=\".25\" stroke-dasharray=\"2 6\"/>\n        <g id=\"gua\" font-family=\"serif\" font-size=\"20\" fill=\"#c9a06a\"></g>\n\n        <!-- 八门 -->\n        <circle r=\"186\" fill=\"none\" stroke=\"#a3c9bb\" stroke-opacity=\".25\"/>\n        <g id=\"doors\"></g>\n\n        <!-- 九星 -->\n        <circle r=\"150\" fill=\"none\" stroke=\"#8a98a0\" stroke-opacity=\".45\" stroke-dasharray=\"10 4\"/>\n        <g id=\"stars\" font-family=\"'Noto Serif SC',serif\" font-size=\"12\" fill=\"#b4bfb8\"></g>\n\n        <!-- 三奇六仪 -->\n        <circle r=\"112\" fill=\"none\" stroke=\"#a3c9bb\" stroke-opacity=\".35\"/>\n        <g id=\"gans\" font-family=\"'Noto Serif SC',serif\" font-size=\"15\" fill=\"#e6eee8\"></g>\n\n        <!-- 中心 -->\n        <circle r=\"78\" fill=\"none\" stroke=\"#a3c9bb\" stroke-opacity=\".45\"/>\n        <circle r=\"60\" fill=\"url(#core)\" opacity=\".5\"/>\n        <text x=\"0\" y=\"8\" text-anchor=\"middle\" font-family=\"'Noto Serif SC',serif\" font-size=\"30\" fill=\"#ffffff\" letter-spacing=\"2\">中</text>\n        <text x=\"0\" y=\"28\" text-anchor=\"middle\" font-family=\"ui-monospace,monospace\" font-size=\"7\" fill=\"#a9d6c8\" letter-spacing=\"3\">CORE</text>\n        <g id=\"coreRing\" stroke=\"#a3c9bb\" stroke-opacity=\".5\" font-family=\"ui-monospace,monospace\"></g>\n\n        <!-- 十字准星 -->\n        <g stroke=\"#a3c9bb\" stroke-opacity=\".22\">\n          <path d=\"M0 -292 V-268 M0 292 V268 M-292 0 H-268 M292 0 H268\"/>\n          <path d=\"M-20 0 H20 M0 -20 V20\" stroke-opacity=\".5\"/>\n        </g>\n\n        <!-- 轴 -->\n        <g class=\"ring-a\" id=\"ringA\" stroke=\"#c9a06a\" stroke-opacity=\".55\"></g>\n        <g class=\"ring-b\" id=\"ringB\" stroke=\"#a3c9bb\" stroke-opacity=\".5\"></g>\n        <g class=\"ring-c\" id=\"ringC\" stroke=\"#8a98a0\" stroke-opacity=\".6\"></g>\n\n        <!-- 雷达扫掠 -->\n        <g class=\"sweep\" id=\"sweep\"><path d=\"M0 0 L0 -282 A282 282 0 0 1 132 -249 Z\" fill=\"url(#sweepGrad)\" opacity=\".18\"/></g>\n\n        <!-- 外环标记点 -->\n        <g id=\"blips\"></g>\n      </svg>\n    </div>\n  </div>\n</section>\n\n<!-- 状态跑马灯 -->\n<div class=\"status\">\n  <div class=\"status-track\">\n    <span>[ <b>局</b> 阳遁三局 ]</span>\n    <span>[ <b>值符</b> 天辅 · 落巽四 ]</span>\n    <span>[ <b>值使</b> 杜门 · 落巽四 ]</span>\n    <span>[ <b>空亡</b> 辰巳 ]</span>\n    <span>[ <b>旬首</b> 甲午辛 ]</span>\n    <span>[ <b>四柱</b> 丙午 / 己亥 / 辛丑 / 己亥 ]</span>\n    <span>[ <em>状态：示意展示</em> ]</span>\n    <span>[ <b>局</b> 阳遁三局 ]</span>\n    <span>[ <b>值符</b> 天辅 · 落巽四 ]</span>\n    <span>[ <b>值使</b> 杜门 · 落巽四 ]</span>\n    <span>[ <b>空亡</b> 辰巳 ]</span>\n    <span>[ <b>旬首</b> 甲午辛 ]</span>\n    <span>[ <b>四柱</b> 丙午 / 己亥 / 辛丑 / 己亥 ]</span>\n    <span>[ <em>状态：盘面已就绪</em> ]</span>\n  </div>\n</div>\n\n<!-- ===== 引擎 ===== -->\n<section class=\"sec\" id=\"engine\">\n  <div class=\"wrap\">\n    <div class=\"sec-head reveal\">\n      <div>\n        <div class=\"kicker\">ENGINE / 04 MODULES</div>\n        <h2 class=\"sec-title\">把一盘之势，<span>编译成动作</span></h2>\n      </div>\n      <p class=\"sec-note\">DISPLAY ONLY · 示例数据<br>不构成决策依据</p>\n    </div>\n    <div class=\"cards reveal\">\n      <div class=\"card\">\n        <span class=\"idx\">MOD.01 / CAST</span>\n        <h4>定局排盘</h4>\n        <p>节气 → 阴阳遁 → 局数，逐层收敛。四柱一键成盘，奇仪落宫自动对位。</p>\n        <div class=\"meter\"><span>LOAD</span><div class=\"bar\" style=\"--v:92%\"></div><span>92</span></div>\n      </div>\n      <div class=\"card\">\n        <span class=\"idx\">MOD.02 / SCAN</span>\n        <h4>宫位扫描</h4>\n        <p>神、星、门、干四层叠加，扫描旺衰与生克，定位真正的核心宫。</p>\n        <div class=\"meter\"><span>DEPTH</span><div class=\"bar\" style=\"--v:78%\"></div><span>04</span></div>\n      </div>\n      <div class=\"card\">\n        <span class=\"idx\">MOD.03 / DB</span>\n        <h4>格局库</h4>\n        <p>查阅奇门基础知识与格局资料，结合具体盘面学习。</p>\n        <div class=\"meter\"><span>INDEX</span><div class=\"bar\" style=\"--v:68%\"></div><span>68</span></div>\n      </div>\n      <div class=\"card\">\n        <span class=\"idx\">MOD.04 / LOG</span>\n        <h4>复盘日志</h4>\n        <p>判断与结果一并入库。偏差值留档，下一次的校准靠它。</p>\n        <div class=\"meter\"><span>FEED</span><div class=\"bar\" style=\"--v:86%\"></div><span>1.2K</span></div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ===== 九宫矩阵 ===== -->\n<section class=\"sec\" id=\"board\" style=\"padding-top:0\">\n  <div class=\"wrap\">\n    <div class=\"sec-head reveal\">\n      <div>\n        <div class=\"kicker\">MATRIX / 九宫示意 · 非实时盘面</div>\n        <h2 class=\"sec-title\">一宫四层，<span>层层见事</span></h2>\n      </div>\n      <p class=\"sec-note\">离九为值符之宫<br>景门主文书声名</p>\n    </div>\n\n    <div class=\"hud-grid\">\n      <div class=\"board reveal\" id=\"board9\">\n        <div class=\"hcell\"><div class=\"t\"><span>九天</span><b>天辅</b></div><div class=\"c\">壬<small>杜门</small></div><div class=\"b\"><span>巽四</span><span>乙</span></div></div>\n        <div class=\"hcell lit\"><div class=\"t\"><span>值符</span><b>天英</b></div><div class=\"c\">戊<small>景门</small></div><div class=\"b\"><span>离九</span><span>丙</span></div></div>\n        <div class=\"hcell\"><div class=\"t\"><span>螣蛇</span><b>天芮</b></div><div class=\"c\">癸<small>死门</small></div><div class=\"b\"><span>坤二</span><span>丁</span></div></div>\n        <div class=\"hcell\"><div class=\"t\"><span>太阴</span><b>天冲</b></div><div class=\"c\">庚<small>伤门</small></div><div class=\"b\"><span>震三</span><span>壬</span></div></div>\n        <div class=\"hcell center\"><div class=\"t\"><span></span><b>中五</b></div><div class=\"c\">中<small>寄坤二</small></div><div class=\"b\"><span>天禽</span><span>—</span></div></div>\n        <div class=\"hcell\"><div class=\"t\"><span>六合</span><b>天柱</b></div><div class=\"c\">辛<small>惊门</small></div><div class=\"b\"><span>兑七</span><span>癸</span></div></div>\n        <div class=\"hcell\"><div class=\"t\"><span>白虎</span><b>天任</b></div><div class=\"c\">丙<small>生门</small></div><div class=\"b\"><span>艮八</span><span>戊</span></div></div>\n        <div class=\"hcell\"><div class=\"t\"><span>玄武</span><b>天蓬</b></div><div class=\"c\">乙<small>休门</small></div><div class=\"b\"><span>坎一</span><span>辛</span></div></div>\n        <div class=\"hcell\"><div class=\"t\"><span>九地</span><b>天心</b></div><div class=\"c\">丁<small>开门</small></div><div class=\"b\"><span>乾六</span><span>庚</span></div></div>\n      </div>\n\n      <div class=\"terminal reveal\">\n        <div class=\"term-bar\"><span></span><span></span><span></span><em>qimen://readout/example · 示例</em></div>\n        <div class=\"term-body\">\n          <div><span class=\"p\">qimen&gt;</span> <span class=\"k\">load --time now</span></div>\n          <div><span class=\"p\">→</span> 四柱 <span class=\"m\">丙午 己亥 辛丑 己亥</span></div>\n          <div><span class=\"p\">→</span> 节气 立冬 · 阳遁 <span class=\"m\">三局</span></div>\n          <div><span class=\"p\">→</span> 值符 <span class=\"g\">天辅</span> 值使 <span class=\"g\">杜门</span></div>\n          <div><span class=\"p\">→</span> 空亡 辰巳 · 旬首 甲午辛</div>\n          <div><span class=\"p\">qimen&gt;</span> <span class=\"k\">scan core</span></div>\n          <div><span class=\"p\">→</span> 核心宫 <span class=\"g\">离九</span> · 值符临宫</div>\n          <div><span class=\"p\">→</span> 门象 景门 · 主 文书 / 声名 / 契约</div>\n          <div><span class=\"p\">→</span> 提示 火性易急，宜先立据再扩张</div>\n          <div><span class=\"p\">qimen&gt;</span> <span class=\"k\">watch --palace 离九</span></div>\n          <div><span class=\"p\">→</span> 六仪 戊 己 庚 辛 壬 癸</div>\n          <div><span class=\"p\">→</span> 三奇 乙 丙 丁 · 格局 三奇得使</div>\n          <div><span class=\"p\">→</span> 关注 文书契约的落笔时点</div>\n          <div><span class=\"p\">→</span> 应期 三日内 / 五日后</div>\n          <div><span class=\"p\">qimen&gt;</span> <span class=\"cursor\"></span></div>\n        </div>\n        <div class=\"term-foot\"><span>LAT 42ms</span><span>SESSION / QM-031</span></div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ===== 日志 ===== -->\n<section class=\"sec\" id=\"logs\" style=\"border-top:1px solid rgba(163,201,187,.16)\"><div class=\"wrap\"><div class=\"sec-head reveal\"><div><div class=\"kicker\">ARCHIVE / 案例学习</div><h2 class=\"sec-title\">从案例中，<span>学习与复盘</span></h2></div><a class=\"btn\" href=\"/cases\" target=\"_top\">查看案例</a></div></div></section>\n\n<!-- ===== CTA ===== -->\n<section class=\"cta\" id=\"cta\">\n  <div class=\"ring\"></div>\n  <div class=\"wrap cta-inner reveal\">\n    <h2>盘面已就绪，<span>等你落子</span></h2>\n    <p>NO DESTINY / ONLY TRAJECTORY<br>奇门不是宿命，是一张更清晰的地图</p>\n    <a class=\"btn hot\" href=\"/divination\" target=\"_top\">接 入 盘 面 <span>→</span></a>\n  </div>\n</section>\n\n<footer>\n  <div class=\"wrap foot\">\n    <span>玄枢 QIMEN PROTOCOL · 演示页面 / 盘面数据仅供研习</span>\n    <span class=\"ok\">ALL SYSTEMS NOMINAL</span>\n  </div>\n</footer>\n\n<script>\nconst NS='http://www.w3.org/2000/svg';\nfunction el(tag,attrs={}){const e=document.createElementNS(NS,tag);for(const k in attrs)e.setAttribute(k,attrs[k]);return e;}\nconst polar=(a,r,deg=0)=>{const rad=(a-90)*Math.PI/180;return [r*Math.cos(rad),r*Math.sin(rad)];};\n\n/* 刻度 */\nconst ticks=document.getElementById('ticks');\nfor(let d=0;d<360;d+=2){\n  const long=d%30===0?12:(d%10===0?7:3.5);\n  const [x1,y1]=polar(d,282), [x2,y2]=polar(d,282-long);\n  ticks.appendChild(el('line',{x1,y1,x2,y2,'stroke-width':d%30===0?1.4:.7,'stroke-opacity':d%30===0?.9:.45}));\n}\nconst degs=document.getElementById('degrees');\nfor(let d=0;d<360;d+=30){\n  const [x,y]=polar(d,266);\n  const t=el('text',{x,y,fill:'#4e6e62','text-anchor':'middle','dominant-baseline':'middle'});\n  t.textContent=String(d).padStart(3,'0');degs.appendChild(t);\n}\n\n/* 二十四山 */\nconst SHAN=['子','癸','丑','艮','寅','甲','卯','乙','辰','巽','巳','丙','午','丁','未','坤','申','庚','酉','辛','戌','乾','亥','壬'];\nconst shanG=document.getElementById('shan');\nSHAN.forEach((s,i)=>{\n  const a=i*15;const [x,y]=polar(a,234);\n  const t=el('text',{x,y,'text-anchor':'middle','dominant-baseline':'middle'});\n  t.textContent=s;\n  t.setAttribute('fill',['艮','巽','坤','乾'].includes(s)?'#d8bb8c':'#a8d2c6');\n  t.setAttribute('font-size',['艮','巽','坤','乾'].includes(s)?16:13);\n  shanG.appendChild(t);\n});\n\n/* 八卦 */\nconst GUA=['☵','☶','☳','☴','☲','☷','☱','☰']; // 坎艮震巽离坤兑乾（后天方位）\nconst guaG=document.getElementById('gua');\nGUA.forEach((g,i)=>{\n  const a=i*45;const [x,y]=polar(a,206);\n  const t=el('text',{x,y,'text-anchor':'middle','dominant-baseline':'middle',fill:'#c9a06a'});\n  t.textContent=g;guaG.appendChild(t);\n});\n\n/* 八门 8 方位 */\nconst DOORS=['休','生','伤','杜','景','死','惊','开'];\nconst doorsG=document.getElementById('doors');\nDOORS.forEach((d,i)=>{\n  const a=i*45, [x,y]=polar(a,172);\n  const g=el('g',{});\n  g.appendChild(el('rect',{x:x-15,y:y-11,width:30,height:22,fill:'rgba(6,16,14,.85)',stroke:'#a3c9bb','stroke-opacity':.5,'stroke-width':.8}));\n  const t=el('text',{x, y:y+5,'text-anchor':'middle','font-family':\"'Noto Serif SC',serif\",'font-size':13,fill:'#c9e4da'});\n  t.textContent=d;g.appendChild(t);doorsG.appendChild(g);\n});\n\n/* 九星 9 方位 */\nconst STARS=['天蓬','天芮','天冲','天辅','天禽','天心','天柱','天任','天英'];\nconst starsG=document.getElementById('stars');\nSTARS.forEach((s,i)=>{\n  const a=i*40, [x,y]=polar(a,131);\n  const t=el('text',{x,y,'text-anchor':'middle','dominant-baseline':'middle','font-size':11});\n  t.textContent=s;starsG.appendChild(t);\n});\n\n/* 三奇六仪 */\nconst GANS=['戊','己','庚','辛','壬','癸','丁','丙','乙'];\nconst gansG=document.getElementById('gans');\nGANS.forEach((g,i)=>{\n  const a=i*40, [x,y]=polar(a,95);\n  const t=el('text',{x,y,'text-anchor':'middle','dominant-baseline':'middle',fill:i<3?'#efe0c8':'#e6eee8'});\n  t.textContent=g;gansG.appendChild(t);\n});\n\n/* 内环 rotate 标尺 */\nconst cr=document.getElementById('coreRing');\nfor(let d=0;d<360;d+=15){\n  const [x1,y1]=polar(d,74),[x2,y2]=polar(d,66);\n  cr.appendChild(el('line',{x1,y1,x2,y2,'stroke-width':.6,'stroke-opacity':.4}));\n}\n\n/* 三支动轴 */\nfunction axis(id,r,len,count,tickLen){\n  const g=document.getElementById(id);\n  for(let i=0;i<count;i++){\n    const a=i*(360/count);\n    const [x1,y1]=polar(a,r-len), [x2,y2]=polar(a,r);\n    g.appendChild(el('line',{x1,y1,x2,y2,'stroke-width':.8}));\n    const [tx,ty]=polar(a+ (360/count)/2, r-len*.4);\n    g.appendChild(el('circle',{cx:tx,cy:ty,r:1.6,fill:'currentColor','fill-opacity':.6}));\n  }\n}\naxis('ringA',205,34,12);\naxis('ringB',160,20,18);\naxis('ringC',88,12,36);\n\n/* 外环 blips */\nconst blips=document.getElementById('blips');\n[[12,268,'#c9a06a'],[78,268,'#a3c9bb'],[155,268,'#a3c9bb'],[212,270,'#8a98a0'],[298,268,'#c9a06a'],[340,270,'#a3c9bb']].forEach(([a,r,c])=>{\n  const [x,y]=polar(a,r);\n  const dot=el('circle',{cx:x,cy:y,r:2.6,fill:c,'fill-opacity':.9});\n  dot.setAttribute('style',`filter:drop-shadow(0 0 6px ${c})`);\n  blips.appendChild(dot);\n  const [lx,ly]=polar(a,r+9);\n  const l=el('line',{x1:x,y1:y,x2:lx,y2:ly,stroke:c,'stroke-opacity':.5,'stroke-width':1});\n  blips.appendChild(l);\n});\n\n/* 动画：扫掠、三环反向缓慢转 */\nconst sweep=document.getElementById('sweep');\nlet ang=0;\nfunction spin(){\n  ang=(ang+0.55)%360;\n  sweep.setAttribute('transform',`rotate(${ang})`);\n  requestAnimationFrame(spin);\n}\nspin();\nconst rA=document.getElementById('ringA'), rB=document.getElementById('ringB'), rC=document.getElementById('ringC');\nlet a1=0,a2=0,a3=0;\nfunction slow(){\n  a1=(a1+0.12)%360; a2=(a2-0.08+360)%360; a3=(a3+0.05)%360;\n  rA.setAttribute('transform',`rotate(${a1})`);\n  rB.setAttribute('transform',`rotate(${a2})`);\n  rC.setAttribute('transform',`rotate(${a3})`);\n  requestAnimationFrame(slow);\n}\nslow();\n\n/* 导航 & 出现 */\nconst hdr=document.getElementById('hdr');\nconst links=[...document.querySelectorAll('.nav-links a')];\nwindow.addEventListener('scroll',()=>{\n  hdr.classList.toggle('scrolled',window.scrollY>30);\n  let cur='top';\n  links.forEach(a=>{const id=a.getAttribute('href').slice(1);const el=document.getElementById(id);if(el&&el.getBoundingClientRect().top<=140)cur=id;});\n  links.forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+cur));\n},{passive:true});\nconst io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}}),{threshold:.1});\ndocument.querySelectorAll('.reveal').forEach(x=>io.observe(x));\n</script>\n</body>\n</html>\n"
const paperHomepage = "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>奇门遁甲 · 玄枢协议 / 宣纸</title>\n<link rel=\"stylesheet\" href=\"https://miaoda.feishu.cn/fonts/css2?family=Noto+Serif+SC:wght@400;600;700;900&family=Noto+Sans+SC:wght@300;400;500;700&display=swap\">\n<style>\n:root{\n  --bg:#081311;\n  --bg2:#0d1a17;\n  --panel:rgba(13,18,16,.72);\n  --cyan:#a3c9bb;\n  --cyan-dim:rgba(163,201,187,.45);\n  --magenta:#c9a06a;\n  --violet:#8a98a0;\n  --lime:#a9b79a;\n  --text:#dce4de;\n  --dim:#78877f;\n  --mono:ui-monospace,\"SF Mono\",\"JetBrains Mono\",Menlo,Consolas,monospace;\n  --serif:\"Noto Serif SC\",\"Songti SC\",serif;\n  --sans:\"Noto Sans SC\",\"PingFang SC\",sans-serif;\n}\n*{margin:0;padding:0;box-sizing:border-box}\nhtml{scroll-behavior:smooth}\nbody{\n  background:var(--bg);color:var(--text);font-family:var(--sans);font-weight:300;\n  line-height:1.8;overflow-x:hidden;-webkit-font-smoothing:antialiased;\n  background-image:\n    radial-gradient(circle at 22% 8%,rgba(138,152,160,.16),transparent 45%),\n    radial-gradient(circle at 82% 30%,rgba(201,160,106,.10),transparent 42%),\n    radial-gradient(circle at 50% 90%,rgba(163,201,187,.08),transparent 50%);\n  background-attachment:fixed;\n}\n::selection{background:var(--magenta);color:#fff}\n\n/* 扫描线 / 噪点 */\n.scanlines{\n  position:fixed;inset:0;z-index:2;pointer-events:none;opacity:.11;\n  background:repeating-linear-gradient(0deg,rgba(255,255,255,.10) 0 1px,transparent 1px 3px);\n  mix-blend-mode:overlay;\n}\n.noise{\n  position:fixed;inset:0;z-index:3;pointer-events:none;opacity:.07;\n  background-image:url(\"data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='3' stitchTiles='stitch'/><feColorMatrix type='saturate' values='0'/></filter><rect width='160' height='160' filter='n' opacity='0.5'/></svg>\");\n}\n.vignette{position:fixed;inset:0;z-index:4;pointer-events:none;background:radial-gradient(ellipse at 50% 40%,transparent 45%,rgba(0,0,0,.55) 100%)}\n\n.wrap{max-width:1300px;margin:0 auto;padding:0 44px;position:relative;z-index:6}\n\n/* ===== 导航 ===== */\nheader{\n  position:fixed;top:0;left:0;right:0;z-index:30;\n  border-bottom:1px solid rgba(163,201,187,.14);\n  transition:background .4s,box-shadow .4s;\n}\nheader.scrolled{background:rgba(6,11,10,.86);backdrop-filter:blur(16px);box-shadow:0 0 40px rgba(163,201,187,.08)}\n.nav{display:flex;align-items:center;justify-content:space-between;height:76px}\n.brand{display:flex;align-items:center;gap:14px;text-decoration:none;color:var(--text)}\n.mark{\n  width:40px;height:40px;position:relative;display:grid;place-items:center;\n  border:1px solid var(--cyan);color:var(--cyan);font-family:var(--mono);font-size:11px;\n  box-shadow:0 0 14px rgba(163,201,187,.35),inset 0 0 14px rgba(163,201,187,.18);\n  clip-path:polygon(0 0,100% 0,100% 70%,70% 100%,0 100%);\n}\n.brand-txt{font-family:var(--serif);font-size:17px;letter-spacing:5px;color:#eaf2ec;font-weight:600}\n.brand-sub{font-family:var(--mono);font-size:9px;letter-spacing:2.5px;color:var(--cyan);opacity:.8;margin-top:2px}\n.nav-links{display:flex;gap:34px;list-style:none}\n.nav-links a{\n  font-family:var(--mono);font-size:11px;letter-spacing:2px;color:var(--dim);text-decoration:none;\n  position:relative;padding:6px 2px;transition:color .3s,text-shadow .3s;\n}\n.nav-links a:hover,.nav-links a.active{color:var(--cyan);text-shadow:0 0 12px rgba(163,201,187,.6)}\n.nav-links a.active::after{content:\"\";position:absolute;left:0;right:0;bottom:-2px;height:1px;background:var(--cyan);box-shadow:0 0 8px var(--cyan)}\n.btn{\n  display:inline-flex;align-items:center;gap:10px;padding:11px 24px;cursor:pointer;\n  font-family:var(--mono);font-size:12px;letter-spacing:2px;text-decoration:none;\n  color:var(--cyan);border:1px solid var(--cyan);background:rgba(163,201,187,.05);\n  clip-path:polygon(0 0,calc(100% - 12px) 0,100% 12px,100% 100%,12px 100%,0 calc(100% - 12px));\n  transition:all .3s;\n}\n.btn:hover{background:rgba(163,201,187,.16);box-shadow:0 0 24px rgba(163,201,187,.35);color:#fff}\n.btn.hot{color:#14100a;background:linear-gradient(100deg,var(--magenta),#d9bc8e);border-color:transparent;font-weight:700;box-shadow:0 0 28px rgba(201,160,106,.45)}\n.btn.hot:hover{color:#14100a;box-shadow:0 0 40px rgba(201,160,106,.7)}\n\n/* ===== 首屏 ===== */\n.hero{position:relative;min-height:100svh;display:flex;align-items:center;padding:130px 0 60px;overflow:hidden}\n.hero::before{\n  content:\"\";position:absolute;inset:0;z-index:1;\n  background-image:linear-gradient(rgba(163,201,187,.09) 1px,transparent 1px),linear-gradient(90deg,rgba(163,201,187,.09) 1px,transparent 1px);\n  background-size:150px 150px;\n  mask-image:radial-gradient(ellipse at 62% 45%,#000 0%,transparent 70%);\n  -webkit-mask-image:radial-gradient(ellipse at 62% 45%,#000 0%,transparent 70%);\n  transform:perspective(600px) rotateX(52deg) scale(1.6);\n  transform-origin:50% 80%;opacity:.35;\n}\n.hero-inner{display:grid;grid-template-columns:1fr 1.05fr;gap:40px;align-items:center;width:100%}\n.hero-inner>*{min-width:0}\n.eyebrow{\n  font-family:var(--mono);font-size:11px;letter-spacing:4px;color:var(--cyan);\n  display:flex;align-items:center;gap:12px;margin-bottom:28px;\n}\n.eyebrow .dot{width:6px;height:6px;background:var(--magenta);box-shadow:0 0 10px var(--magenta);animation:blink 1.6s steps(2) infinite}\n@keyframes blink{50%{opacity:.25}}\nh1{\n  position:relative;font-family:var(--serif);font-weight:900;\n  font-size:clamp(56px,7vw,100px);line-height:1.06;letter-spacing:14px;color:#f1f5f1;\n  text-shadow:0 0 30px rgba(163,201,187,.28),0 0 80px rgba(138,152,160,.2);\n}\nh1 em{font-style:normal;color:var(--cyan)}\nh1::before,h1::after{\n  content:attr(data-text);position:absolute;inset:0;opacity:0;pointer-events:none;\n}\nh1::before{color:var(--magenta);left:2px;text-shadow:-2px 0 var(--magenta)}\nh1::after{color:var(--cyan);left:-2px;text-shadow:2px 0 var(--cyan)}\nh1:hover::before{opacity:.30;animation:glitch-a .5s steps(2) infinite}\nh1:hover::after{opacity:.30;animation:glitch-b .5s steps(2) infinite}\n@keyframes glitch-a{0%{clip-path:inset(0 0 72% 0)}25%{clip-path:inset(40% 0 30% 0)}50%{clip-path:inset(80% 0 4% 0)}75%{clip-path:inset(20% 0 60% 0)}100%{clip-path:inset(0 0 0 0)}}\n@keyframes glitch-b{0%{clip-path:inset(60% 0 10% 0)}25%{clip-path:inset(10% 0 78% 0)}50%{clip-path:inset(30% 0 45% 0)}75%{clip-path:inset(70% 0 8% 0)}100%{clip-path:inset(0 0 0 0)}}\n.hero-sub{\n  font-family:var(--mono);font-size:13px;letter-spacing:6px;color:#beddd2;margin-top:16px;\n}\n.hero-sub span{color:var(--magenta)}\n.hero-desc{max-width:470px;margin-top:26px;color:#94a39b;font-size:14px;line-height:2;letter-spacing:.4px}\n.hero-desc b{color:var(--cyan);font-weight:500}\n.hero-actions{display:flex;gap:14px;margin-top:40px;flex-wrap:wrap}\n.hero-stats{display:flex;gap:38px;margin-top:50px;flex-wrap:wrap}\n.stat{border-left:1px solid rgba(163,201,187,.35);padding-left:14px}\n.stat b{display:block;font-family:var(--mono);font-size:22px;color:#eaf2ec;letter-spacing:1px;line-height:1.3;text-shadow:0 0 14px rgba(163,201,187,.45)}\n.stat i{font-style:normal;font-family:var(--mono);font-size:9px;color:var(--dim);letter-spacing:2px}\n\n/* 仪器 */\n.instrument{position:relative;display:grid;place-items:center;padding:10px;min-width:0}\n.instrument svg{width:min(600px,100%);overflow:visible;filter:drop-shadow(0 0 24px rgba(163,201,187,.12))}\n.instrument::after{\n  content:\"\";position:absolute;inset:12%;border-radius:50%;pointer-events:none;\n  background:radial-gradient(circle,rgba(163,201,187,.10),transparent 62%);\n}\n.hud{\n  position:absolute;font-family:var(--mono);font-size:9px;letter-spacing:1.5px;color:var(--cyan);\n  border:1px solid rgba(163,201,187,.30);background:rgba(6,12,10,.8);padding:5px 9px;\n  white-space:nowrap;backdrop-filter:blur(4px);\n}\n.hud.m{border-color:rgba(201,160,106,.4);color:#d8bb8c}\n.hud i{font-style:normal;display:block;font-size:8px;color:var(--dim);letter-spacing:1px}\n.hud.tl{left:-2%;top:2%}\n.hud.tr{right:-2%;top:-1%}\n.hud.bl{left:-1%;bottom:3%}\n.hud.br{right:-2%;bottom:7%}\n.hud::before{content:\"\";position:absolute;left:-10px;top:50%;width:9px;height:1px;background:rgba(163,201,187,.5)}\n.hud.tr::before,.hud.br::before{left:auto;right:-10px}\n\n/* 状态条 */\n.status{\n  border-top:1px solid rgba(163,201,187,.18);border-bottom:1px solid rgba(163,201,187,.18);\n  background:linear-gradient(90deg,rgba(163,201,187,.06),transparent 60%);\n  overflow:hidden;white-space:nowrap;font-family:var(--mono);font-size:11px;letter-spacing:2px;\n}\n.status-track{display:flex;gap:52px;padding:15px 0;color:#8ca096;animation:slide 38s linear infinite;width:max-content}\n.status b{color:var(--cyan);font-weight:500}\n.status em{color:var(--magenta);font-style:normal}\n@keyframes slide{from{transform:translateX(0)}to{transform:translateX(-50%)}}\n\n/* ===== 通用 ===== */\nsection{position:relative;z-index:6}\n.sec{padding:104px 0}\n.sec-head{margin-bottom:54px;display:flex;align-items:flex-end;justify-content:space-between;gap:40px;flex-wrap:wrap}\n.kicker{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:var(--magenta);display:flex;align-items:center;gap:10px;margin-bottom:18px}\n.kicker::before{content:\"//\";color:var(--cyan)}\n.sec-title{font-family:var(--serif);font-size:clamp(26px,3.3vw,40px);font-weight:700;letter-spacing:4px;line-height:1.45;color:#eff4f0}\n.sec-title span{color:var(--cyan);text-shadow:0 0 24px rgba(163,201,187,.35)}\n.sec-note{max-width:340px;font-family:var(--mono);font-size:10px;line-height:2;letter-spacing:1.5px;color:var(--dim);text-align:right;border-right:1px solid rgba(163,201,187,.25);padding-right:16px}\n\n/* 模块卡 */\n.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\n.card{\n  position:relative;padding:34px 26px 30px;background:var(--panel);border:1px solid rgba(163,201,187,.18);\n  transition:border-color .35s,transform .35s,box-shadow .35s;overflow:hidden;\n}\n.card::before,.card::after{content:\"\";position:absolute;width:14px;height:14px;border:1px solid var(--cyan);transition:all .35s}\n.card::before{left:-1px;top:-1px;border-right:0;border-bottom:0}\n.card::after{right:-1px;bottom:-1px;border-left:0;border-top:0}\n.card:hover{border-color:rgba(163,201,187,.6);transform:translateY(-4px);box-shadow:0 14px 40px rgba(0,0,0,.5),0 0 30px rgba(163,201,187,.12)}\n.card:hover::before,.card:hover::after{width:26px;height:26px;box-shadow:0 0 10px rgba(163,201,187,.5)}\n.card .idx{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:var(--magenta);margin-bottom:26px;display:block}\n.card h4{font-family:var(--serif);font-size:18px;letter-spacing:3px;color:#e6eee8;font-weight:600;margin-bottom:12px}\n.card p{font-size:12.5px;color:#86948c;line-height:1.95;min-height:72px}\n.card .meter{margin-top:22px;display:flex;align-items:center;gap:10px;font-family:var(--mono);font-size:9px;color:var(--dim);letter-spacing:1px}\n.card .meter .bar{flex:1;height:2px;background:rgba(163,201,187,.14);position:relative}\n.card .meter .bar::after{content:\"\";position:absolute;left:0;top:0;height:100%;width:var(--v,80%);background:linear-gradient(90deg,var(--cyan),var(--magenta));box-shadow:0 0 8px rgba(163,201,187,.6)}\n\n/* 九宫 HUD */\n.hud-grid{display:grid;grid-template-columns:1.02fr .98fr;gap:34px;align-items:stretch}\n.board{\n  position:relative;display:grid;grid-template-columns:repeat(3,1fr);gap:1px;\n  background:rgba(163,201,187,.18);border:1px solid rgba(163,201,187,.28);padding:1px;\n  box-shadow:0 0 40px rgba(163,201,187,.08),inset 0 0 60px rgba(163,201,187,.04);\n}\n.hcell{\n  position:relative;background:rgba(9,13,12,.94);aspect-ratio:1/.78;padding:10px;\n  display:flex;flex-direction:column;justify-content:space-between;min-width:0;overflow:hidden;\n}\n.hcell::after{\n  content:\"\";position:absolute;inset:0;pointer-events:none;\n  background:linear-gradient(180deg,rgba(163,201,187,.10),transparent 40%);\n  opacity:0;transition:opacity .3s;\n}\n.hcell:hover::after{opacity:1}\n.hcell .t{display:flex;justify-content:space-between;font-family:var(--mono);font-size:8.5px;color:#5e7268;letter-spacing:1px}\n.hcell .t b{color:var(--magenta);font-weight:400}\n.hcell .c{font-family:var(--serif);font-size:24px;color:#ddece3;text-align:center;line-height:1.2;text-shadow:0 0 16px rgba(163,201,187,.35)}\n.hcell .c small{display:block;font-family:var(--mono);font-size:8px;letter-spacing:1.5px;color:var(--cyan);margin-top:3px}\n.hcell .b{display:flex;justify-content:space-between;font-family:var(--mono);font-size:8px;color:#5e7268}\n.hcell.center{background:radial-gradient(circle at 50% 50%,rgba(163,201,187,.22),rgba(9,13,12,.95) 62%)}\n.hcell.center .c{font-size:30px;color:#fff}\n.hcell.lit{background:linear-gradient(180deg,rgba(201,160,106,.12),rgba(9,13,12,.95))}\n.hcell.lit .c{color:#efe0c8}\n\n/* 终端 */\n.terminal{\n  background:rgba(4,9,8,.9);border:1px solid rgba(163,201,187,.24);display:flex;flex-direction:column;\n  box-shadow:0 0 30px rgba(0,0,0,.6),inset 0 0 50px rgba(163,201,187,.04);\n}\n.term-bar{display:flex;align-items:center;gap:8px;padding:9px 12px;border-bottom:1px solid rgba(163,201,187,.18);font-family:var(--mono);font-size:9px;color:var(--dim);letter-spacing:1px}\n.term-bar span{width:7px;height:7px;border-radius:50%;background:#33453f}\n.term-bar span:first-child{background:var(--magenta);box-shadow:0 0 8px var(--magenta)}\n.term-bar span:nth-child(2){background:var(--cyan);box-shadow:0 0 8px var(--cyan)}\n.term-bar em{font-style:normal;margin-left:6px;color:#7f9288}\n.term-body{padding:20px 18px;font-family:var(--mono);font-size:11.5px;line-height:2.05;color:#8fa199;flex:1;overflow:hidden}\n.term-body .p{color:var(--cyan)}\n.term-body .k{color:#dce4de}\n.term-body .g{color:var(--lime)}\n.term-body .m{color:var(--magenta)}\n.cursor{display:inline-block;width:7px;height:13px;background:var(--cyan);vertical-align:-1px;animation:blink 1.1s steps(2) infinite;box-shadow:0 0 8px var(--cyan)}\n.term-foot{border-top:1px solid rgba(163,201,187,.14);padding:10px 14px;display:flex;justify-content:space-between;font-family:var(--mono);font-size:9px;color:#5e7268;letter-spacing:1px}\n\n/* 日志 */\n.logs{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\n.log{\n  display:block;text-decoration:none;color:inherit;padding:26px 24px 22px;background:rgba(10,15,13,.6);\n  border:1px solid rgba(163,201,187,.16);position:relative;transition:all .35s;\n}\n.log:hover{border-color:rgba(201,160,106,.55);background:rgba(201,160,106,.04);box-shadow:0 0 32px rgba(201,160,106,.1)}\n.log .tag{font-family:var(--mono);font-size:9px;letter-spacing:1.5px;color:var(--magenta);margin-bottom:16px;display:flex;justify-content:space-between}\n.log .tag em{font-style:normal;color:#5e7268}\n.log h4{font-family:var(--serif);font-size:17px;line-height:1.6;letter-spacing:1.5px;color:#e4ede7;font-weight:600;margin-bottom:12px}\n.log p{font-size:12px;color:#86948c;line-height:1.9}\n.log .foot{margin-top:18px;font-family:var(--mono);font-size:9px;color:var(--cyan);letter-spacing:1px;opacity:.7}\n\n/* CTA */\n.cta{padding:120px 0 110px;text-align:center;position:relative;border-top:1px solid rgba(163,201,187,.18);overflow:hidden}\n.cta .ring{\n  position:absolute;left:50%;top:50%;width:min(900px,110vw);aspect-ratio:1;transform:translate(-50%,-50%);\n  border:1px solid rgba(163,201,187,.12);border-radius:50%;\n  box-shadow:0 0 80px rgba(163,201,187,.06) inset;\n}\n.cta .ring::before,.cta .ring::after{content:\"\";position:absolute;inset:12%;border:1px solid rgba(201,160,106,.14);border-radius:50%}\n.cta .ring::after{inset:26%;border-color:rgba(163,201,187,.15)}\n.cta-inner{position:relative;z-index:7}\n.cta h2{font-family:var(--serif);font-size:clamp(30px,4.2vw,54px);letter-spacing:9px;font-weight:700;color:#f1f5f1;line-height:1.5;text-shadow:0 0 40px rgba(163,201,187,.25)}\n.cta h2 span{color:var(--cyan)}\n.cta p{max-width:520px;margin:22px auto 38px;font-family:var(--mono);font-size:11px;letter-spacing:2px;line-height:2;color:#78877f}\n.cta .btn{padding:15px 40px;font-size:13px}\n\nfooter{border-top:1px solid rgba(163,201,187,.14);padding:34px 0;position:relative;z-index:7;font-family:var(--mono);font-size:9px;letter-spacing:1.5px;color:#54635c}\n.foot{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}\n.foot .ok{color:var(--lime)}\n.foot .ok::before{content:\"●\";margin-right:6px;font-size:8px}\n\n.reveal{opacity:0;transform:translateY(24px);transition:opacity .9s ease,transform .9s ease}\n.reveal.in{opacity:1;transform:none}\n\n@media (max-width:1080px){\n  .hero-inner{grid-template-columns:1fr;gap:30px}\n  .hero{padding-top:118px}\n  .instrument{order:-1;margin-top:10px}\n  .instrument svg{width:min(520px,86vw)}\n  .hud.tl,.hud.tr{top:8%}\n  .hud.tl{left:0}\n  .hud.tr{top:18%}\n  .cards{grid-template-columns:repeat(2,1fr)}\n  .hud-grid{grid-template-columns:1fr}\n  .logs{grid-template-columns:1fr}\n  .nav-links{display:none}\n  .sec-note{text-align:left;border-right:0;border-left:1px solid rgba(163,201,187,.25);padding:0 0 0 14px}\n}\n@media (max-width:640px){\n  .wrap{padding:0 18px}\n  .sec{padding:76px 0}\n  h1{font-size:48px;letter-spacing:7px}\n  .hero-sub{letter-spacing:3px;font-size:11px}\n  .hero-desc{font-size:13px}\n  .hero-actions .btn{flex:1;justify-content:center}\n  .hero-stats{gap:20px}\n  .stat b{font-size:18px}\n  .cards{grid-template-columns:1fr}\n  .card p{min-height:auto}\n  .instrument svg{width:100%}\n  .hud{font-size:8px;padding:4px 6px}\n  .hud.bl{left:0}\n  .hud.tl,.hud.br{display:none}\n  .hud.br{bottom:18%}\n  .board{padding:1px}\n  .hcell .c{font-size:18px}\n  .hcell .t{font-size:7.5px}\n  .hcell .b{font-size:7px}\n  .brand-txt{font-size:15px;letter-spacing:3px}\n  .nav{height:64px}\n  .mark{width:34px;height:34px}\n  .term-body{font-size:10.5px;padding:16px 12px}\n  .status{font-size:10px}\n  .sec-head{margin-bottom:38px}\n}\n@media (prefers-reduced-motion:reduce){\n  .sweep,.ring-a,.ring-b,.ring-c,.status-track,.dot{animation:none!important}\n}\n\n/* ==== 素雅校准 ==== */\nh1{text-shadow:0 0 26px rgba(163,201,187,.14),0 0 70px rgba(138,152,160,.10)}\n.instrument svg{filter:drop-shadow(0 0 18px rgba(163,201,187,.08))}\n.btn.hot{background:rgba(201,160,106,.10);border:1px solid rgba(201,160,106,.65);color:#e6d3b1;font-weight:500;box-shadow:0 0 16px rgba(201,160,106,.10)}\n.btn.hot:hover{background:rgba(201,160,106,.18);color:#f4e7cf;box-shadow:0 0 26px rgba(201,160,106,.18)}\n\n/* ================= 宣纸主题 ================= */\n.paper-fiber{\n  position:fixed;inset:0;z-index:3;pointer-events:none;opacity:.55;\n  background-image:\n    repeating-linear-gradient(90deg,rgba(114,88,52,.05) 0 1px,transparent 1px 3px),\n    repeating-linear-gradient(0deg,rgba(114,88,52,.032) 0 1px,transparent 1px 6px);\n}\n:root{\n  --paper:#f4ecdb;\n  --paper-2:#e7dac1;\n  --ink:#2b251d;\n  --ink-2:#4d4437;\n  --red:#a5372c;\n  --red-deep:#7c2720;\n  --line:rgba(72,56,36,.22);\n  --dim:#8b7f6b;\n  --text:#3a332a;\n}\nbody{\n  background-color:#f4ecdb;\n  background-image:\n    radial-gradient(1000px 720px at 18% -4%, rgba(255,255,255,.78), transparent 62%),\n    radial-gradient(820px 600px at 92% 8%, rgba(226,201,163,.18), transparent 66%),\n    repeating-linear-gradient(94deg, rgba(120,92,52,.026) 0 1px, transparent 1px 7px);\n  background-attachment:fixed;\n  color:var(--text);\n}\n.scanlines{display:none}\n.noise{opacity:.16;mix-blend-mode:multiply}\n.vignette{background:radial-gradient(ellipse at 50% 35%,transparent 38%,rgba(122,92,52,.26) 100%);mix-blend-mode:multiply;opacity:.30}\n::selection{background:var(--red);color:#f7f0e2}\n\n/* 导航 */\nheader{border-bottom:1px solid var(--line)}\nheader.scrolled{background:rgba(239,229,209,.92);backdrop-filter:blur(14px);box-shadow:0 8px 30px rgba(96,72,42,.12)}\n.mark{border-color:var(--red);color:var(--red);box-shadow:none;background:rgba(255,252,244,.5)}\n.brand-txt{color:var(--ink)}\n.brand-sub{color:var(--red);opacity:.9}\n.nav-links a{color:var(--dim)}\n.nav-links a:hover,.nav-links a.active{color:var(--red);text-shadow:none}\n.nav-links a.active::after{background:var(--red);box-shadow:none}\n\n/* 按钮 */\n.btn{color:var(--red-deep);border:1px solid rgba(165,55,44,.55);background:rgba(255,252,246,.55);box-shadow:none}\n.btn:hover{background:rgba(165,55,44,.08);color:var(--red-deep);box-shadow:none}\n.btn.hot{background:var(--red);border:1px solid var(--red);color:#fbf3e4;font-weight:500;box-shadow:0 2px 12px rgba(140,45,30,.18)}\n.btn.hot:hover{background:var(--red-deep);border-color:var(--red-deep);color:#fff6e8;box-shadow:0 4px 18px rgba(120,39,32,.24)}\n\n/* 首屏 */\n.hero::before{\n  background-image:linear-gradient(rgba(140,60,40,.10) 1px,transparent 1px),linear-gradient(90deg,rgba(140,60,40,.10) 1px,transparent 1px);\n  opacity:.5;\n}\n.eyebrow{color:var(--red)}\n.eyebrow .dot{background:var(--red);box-shadow:none;animation:none}\nh1{color:var(--ink);text-shadow:0 1px 0 rgba(255,255,255,.55),0 18px 40px rgba(90,62,30,.10)}\nh1 em{color:var(--red)}\nh1::before,h1::after{display:none}\n.hero-sub{color:var(--ink-2)}\n.hero-sub span{color:var(--red)}\n.hero-desc{color:var(--ink-2)}\n.hero-desc b{color:var(--red-deep);font-weight:500}\n.stat{border-left:1px solid rgba(165,55,44,.4)}\n.stat b{color:var(--ink);text-shadow:none}\n.stat i{color:var(--dim)}\n\n/* 罗盘 */\n.instrument svg{filter:drop-shadow(0 14px 28px rgba(96,68,36,.16))}\n.instrument::after{background:radial-gradient(circle,rgba(255,252,243,.75),transparent 65%)}\n\n/* SVG 重着色（属性选择器覆盖 presentation 属性） */\n#compass [stroke=\"#a3c9bb\"]{stroke:#5b5344}\n#compass [stroke=\"#c9a06a\"]{stroke:#a5372c}\n#compass [stroke=\"#8a98a0\"]{stroke:#7e7462}\n#compass [fill=\"#4e6e62\"]{fill:#8a7f6b}\n#compass [fill=\"#a8d2c6\"]{fill:#3e382e}\n#compass [fill=\"#c9a06a\"]{fill:#a5372c}\n#compass [fill=\"#b4bfb8\"]{fill:#3f382c}\n#compass [fill=\"#e6eee8\"]{fill:#2e2a23}\n#compass [fill=\"#efe0c8\"]{fill:#9b3b2e}\n#compass [fill=\"#d8bb8c\"]{fill:#b0503f}\n#compass [fill=\"#a9d6c8\"]{fill:#7a352b}\n#compass [fill=\"#ffffff\"]{fill:#2b251d}\n#compass [fill=\"rgba(6,16,14,.85)\"]{fill:rgba(249,242,229,.94)}\n#core stop:first-child{stop-color:#fffdf7}\n#core stop:nth-child(2){stop-color:#a5372c}\n#sweepGrad stop{stop-color:#a5372c}\n#sweep{opacity:.45}\n\n#compass [fill=\"#c9e4da\"]{fill:#3b352b}\n#compass [fill=\"#beddd2\"]{fill:#3b352b}\n#compass circle[stroke=\"#5b5344\"]{stroke-opacity:.52}\n#compass circle[stroke=\"#a5372c\"]{stroke-opacity:.32}\n#ticks{opacity:.8}\n#compass [fill=\"#8a7f6b\"]{fill:#7a6f59}\n#compass [fill=\"#a3c9bb\"]{fill:#8a7f6b}\n#compass [fill=\"#8a98a0\"]{fill:#5f5749}\n\n#blips circle{filter:none!important}\n#blips line{stroke-opacity:.28}\n\n.hud{border:1px solid rgba(90,72,48,.35);background:rgba(251,245,233,.94);color:var(--ink);backdrop-filter:none}\n.hud.m{border-color:rgba(165,55,44,.5);color:var(--red-deep)}\n.hud i{color:var(--dim)}\n.hud::before{background:rgba(90,72,48,.5)}\n.hud.m::before{background:rgba(165,55,44,.6)}\n\n/* 状态条 */\n.status{border-top:1px solid var(--line);border-bottom:1px solid var(--line);background:rgba(231,218,193,.5)}\n.status-track{color:var(--ink-2)}\n.status b{color:var(--red-deep);font-weight:500}\n.status em{color:var(--red);font-style:normal}\n\n/* 通用 */\n.kicker{color:var(--red)}\n.kicker::before{color:var(--ink-2)}\n.sec-title{color:var(--ink)}\n.sec-title span{color:var(--red);text-shadow:none}\n.sec-note{color:var(--dim);border-right:1px solid rgba(165,55,44,.35)}\n\n/* 模块卡 */\n.card{background:rgba(253,247,236,.82);border:1px solid rgba(72,56,36,.28);box-shadow:0 1px 0 rgba(255,255,255,.7) inset,0 10px 22px rgba(96,70,38,.05)}\n.card::before,.card::after{border-color:var(--red)}\n.card:hover{border-color:rgba(165,55,44,.55);box-shadow:0 16px 34px rgba(96,70,38,.14);transform:translateY(-4px)}\n.card:hover::before,.card:hover::after{box-shadow:none}\n.card .idx{color:var(--red)}\n.card h4{color:var(--ink)}\n.card p{color:var(--ink-2)}\n.card .meter{color:var(--dim)}\n.card .meter .bar{background:rgba(90,72,48,.18)}\n.card .meter .bar::after{background:linear-gradient(90deg,var(--red),var(--red-deep));box-shadow:none}\n\n/* 九宫 */\n.board{background:rgba(90,72,48,.3);border:1px solid rgba(90,72,48,.4);box-shadow:0 10px 30px rgba(96,70,38,.10)}\n.hcell{background:rgba(247,240,227,.94)}\n.hcell::after{background:linear-gradient(180deg,rgba(165,55,44,.10),transparent 45%)}\n.hcell .t{color:var(--dim)}\n.hcell .t b{color:var(--red)}\n.hcell .c{color:var(--ink);text-shadow:none}\n.hcell .c small{color:var(--red-deep)}\n.hcell .b{color:var(--dim)}\n.hcell.center{background:radial-gradient(circle at 50% 50%,rgba(165,55,44,.11),rgba(247,240,227,.97) 58%)}\n.hcell.center .c{color:var(--ink)}\n.hcell.lit{background:linear-gradient(180deg,rgba(165,55,44,.12),rgba(247,240,227,.97))}\n.hcell.lit .c{color:var(--red-deep)}\n\n/* 终端 */\n.terminal{background:rgba(249,242,229,.92);border:1px solid rgba(90,72,48,.35);box-shadow:0 12px 30px rgba(96,70,38,.12) inset}\n.term-bar{border-bottom:1px solid var(--line);color:var(--dim)}\n.term-bar span{background:#c9b79b}\n.term-bar span:first-child{background:var(--red);box-shadow:none}\n.term-bar span:nth-child(2){background:#b98a4e;box-shadow:none}\n.term-bar em{color:var(--dim)}\n.term-body{color:var(--ink-2)}\n.term-body .p{color:var(--red-deep)}\n.term-body .k{color:var(--ink)}\n.term-body .g{color:#5c7052}\n.term-body .m{color:var(--red)}\n.cursor{background:var(--red);box-shadow:none}\n.term-foot{border-top:1px solid var(--line);color:var(--dim)}\n\n/* 日志 */\n.log{background:rgba(251,245,233,.6);border:1px solid var(--line)}\n.log:hover{border-color:rgba(165,55,44,.55);background:rgba(165,55,44,.05);box-shadow:0 12px 26px rgba(96,70,38,.12)}\n.log .tag{color:var(--red)}\n.log .tag em{color:var(--dim)}\n.log h4{color:var(--ink)}\n.log p{color:var(--ink-2)}\n.log .foot{color:var(--red-deep);opacity:.75}\n\n/* 收尾 */\n.cta{border-top:1px solid var(--line)}\n.cta .ring{border:1px solid rgba(165,55,44,.22);box-shadow:none}\n.cta .ring::before{border-color:rgba(90,72,48,.18)}\n.cta .ring::after{border-color:rgba(165,55,44,.20)}\n.cta h2{color:var(--ink);text-shadow:0 1px 0 rgba(255,255,255,.6)}\n.cta h2 span{color:var(--red)}\n.cta p{color:var(--ink-2)}\n\n\n/* 印章 */\n.seal{\n  position:absolute;right:6.5%;bottom:6%;z-index:7;width:88px;height:88px;\n  border:2px solid rgba(165,55,44,.55);transform:rotate(-3.5deg);\n  display:grid;place-items:center;opacity:.82;pointer-events:none;\n  background:rgba(250,243,229,.25);\n}\n.seal::before{content:\"\";position:absolute;inset:5px;border:1px solid rgba(165,55,44,.42)}\n.seal span{\n  font-family:var(--serif);font-size:24px;line-height:1.15;letter-spacing:2px;\n  color:rgba(165,55,44,.85);writing-mode:vertical-rl;text-align:center;\n  text-shadow:none;\n}\n.seal em{\n  display:none\n}\n@media (max-width:1080px){.seal{display:none}}\n\nfooter{border-top:1px solid var(--line);color:var(--dim)}\n.foot .ok{color:#5b6b4c}\n\n</style>\n</head>\n<body>\n<div class=\"scanlines\"></div>\n<div class=\"noise\"></div>\n<div class=\"vignette\"></div>\n<div class=\"paper-fiber\"></div>\n\n<header id=\"hdr\">\n  <div class=\"wrap nav\">\n    <div aria-hidden=\"true\"></div>\n    <ul class=\"nav-links\">\n      <li><a href=\"#top\" class=\"active\">BOOT</a></li>\n      <li><a href=\"#engine\">ENGINE</a></li>\n      <li><a href=\"#board\">MATRIX</a></li>\n      <li><a href=\"/knowledge\" target=\"_top\">知识库</a></li><li><a href=\"/cases\" target=\"_top\">案例</a></li>\n    </ul>\n    <a class=\"btn hot\" href=\"/divination\" target=\"_top\">接 入 盘 面</a>\n  </div>\n</header>\n\n<!-- ===== 首屏 ===== -->\n<section class=\"hero\" id=\"top\">\n  <div class=\"wrap hero-inner\">\n    <div class=\"hero-copy\">\n      <div class=\"eyebrow\"><span class=\"dot\"></span> SYSTEM ONLINE · 时家奇门 · 转盘</div>\n      <h1 data-text=\"奇门遁甲\">奇门<em>遁甲</em></h1>\n      <div class=\"hero-sub\">CELESTIAL COMPASS <span>/</span> QIMEN DUNJIA</div>\n      <p class=\"hero-desc\">\n        罗盘定方，星盘定时。以<b>节气</b>为时钟，以<b>九宫</b>为矩阵，把三奇六仪、八门九星写入一张可计算的盘面。\n      </p>\n      <div class=\"hero-actions\">\n        <a class=\"btn hot\" href=\"/divination\" target=\"_top\">启动排盘 <span>→</span></a>\n        <a class=\"btn\" href=\"#engine\">查看引擎</a>\n      </div>\n      <div class=\"hero-stats\">\n        <div class=\"stat\"><b>360°</b><i>罗盘刻度</i></div>\n        <div class=\"stat\"><b>24</b><i>山向定位</i></div>\n        <div class=\"stat\"><b>9+8+8</b><i>星门神层</i></div>\n      </div>\n    </div>\n\n    <div class=\"instrument reveal\">\n      <div class=\"hud tl\"><i>LOC</i>31.23°N 121.47°E</div>\n      <div class=\"hud tr m\"><i>JU</i>阳遁三局</div>\n      <div class=\"hud bl\"><i>SHI</i>值使 · 杜门</div>\n      <div class=\"hud br\"><i>FU</i>值符 · 天辅</div>\n\n      <svg id=\"compass\" viewBox=\"-300 -300 600 600\" role=\"img\" aria-label=\"奇门遁甲罗盘与星盘仪\">\n        <defs>\n          <radialGradient id=\"core\" cx=\"50%\" cy=\"50%\" r=\"50%\">\n            <stop offset=\"0%\" stop-color=\"#ffffff\" stop-opacity=\".95\"/>\n            <stop offset=\"35%\" stop-color=\"#a3c9bb\" stop-opacity=\".55\"/>\n            <stop offset=\"100%\" stop-color=\"#a3c9bb\" stop-opacity=\"0\"/>\n          </radialGradient>\n          <linearGradient id=\"sweepGrad\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n            <stop offset=\"0%\" stop-color=\"#a3c9bb\" stop-opacity=\"0\"/>\n            <stop offset=\"100%\" stop-color=\"#a3c9bb\" stop-opacity=\".55\"/>\n          </linearGradient>\n        </defs>\n\n        <!-- 外层刻度 -->\n        <g id=\"ticks\" stroke=\"#a3c9bb\" opacity=\".55\"></g>\n        <g id=\"degrees\" font-family=\"ui-monospace,monospace\" font-size=\"9\" fill=\"#4e6e62\"></g>\n\n        <!-- 二十四山 -->\n        <circle r=\"252\" fill=\"none\" stroke=\"#a3c9bb\" stroke-opacity=\".28\"/>\n        <g id=\"shan\" font-family=\"'Noto Serif SC',serif\" font-size=\"13\" fill=\"#a8d2c6\"></g>\n\n        <!-- 八卦 -->\n        <circle r=\"219\" fill=\"none\" stroke=\"#c9a06a\" stroke-opacity=\".25\" stroke-dasharray=\"2 6\"/>\n        <g id=\"gua\" font-family=\"serif\" font-size=\"20\" fill=\"#c9a06a\"></g>\n\n        <!-- 八门 -->\n        <circle r=\"186\" fill=\"none\" stroke=\"#a3c9bb\" stroke-opacity=\".25\"/>\n        <g id=\"doors\"></g>\n\n        <!-- 九星 -->\n        <circle r=\"150\" fill=\"none\" stroke=\"#8a98a0\" stroke-opacity=\".45\" stroke-dasharray=\"10 4\"/>\n        <g id=\"stars\" font-family=\"'Noto Serif SC',serif\" font-size=\"12\" fill=\"#b4bfb8\"></g>\n\n        <!-- 三奇六仪 -->\n        <circle r=\"112\" fill=\"none\" stroke=\"#a3c9bb\" stroke-opacity=\".35\"/>\n        <g id=\"gans\" font-family=\"'Noto Serif SC',serif\" font-size=\"15\" fill=\"#e6eee8\"></g>\n\n        <!-- 中心 -->\n        <circle r=\"78\" fill=\"none\" stroke=\"#a3c9bb\" stroke-opacity=\".45\"/>\n        <circle r=\"60\" fill=\"url(#core)\" opacity=\".5\"/>\n        <text x=\"0\" y=\"8\" text-anchor=\"middle\" font-family=\"'Noto Serif SC',serif\" font-size=\"30\" fill=\"#ffffff\" letter-spacing=\"2\">中</text>\n        <text x=\"0\" y=\"28\" text-anchor=\"middle\" font-family=\"ui-monospace,monospace\" font-size=\"7\" fill=\"#a9d6c8\" letter-spacing=\"3\">CORE</text>\n        <g id=\"coreRing\" stroke=\"#a3c9bb\" stroke-opacity=\".5\" font-family=\"ui-monospace,monospace\"></g>\n\n        <!-- 十字准星 -->\n        <g stroke=\"#a3c9bb\" stroke-opacity=\".22\">\n          <path d=\"M0 -292 V-268 M0 292 V268 M-292 0 H-268 M292 0 H268\"/>\n          <path d=\"M-20 0 H20 M0 -20 V20\" stroke-opacity=\".5\"/>\n        </g>\n\n        <!-- 轴 -->\n        <g class=\"ring-a\" id=\"ringA\" stroke=\"#c9a06a\" stroke-opacity=\".55\"></g>\n        <g class=\"ring-b\" id=\"ringB\" stroke=\"#a3c9bb\" stroke-opacity=\".5\"></g>\n        <g class=\"ring-c\" id=\"ringC\" stroke=\"#8a98a0\" stroke-opacity=\".6\"></g>\n\n        <!-- 雷达扫掠 -->\n        <g class=\"sweep\" id=\"sweep\"><path d=\"M0 0 L0 -282 A282 282 0 0 1 132 -249 Z\" fill=\"url(#sweepGrad)\" opacity=\".18\"/></g>\n\n        <!-- 外环标记点 -->\n        <g id=\"blips\"></g>\n      </svg>\n    </div>\n  </div>\n  \n</section>\n\n<!-- 状态跑马灯 -->\n<div class=\"status\">\n  <div class=\"status-track\">\n    <span>[ <b>局</b> 阳遁三局 ]</span>\n    <span>[ <b>值符</b> 天辅 · 落巽四 ]</span>\n    <span>[ <b>值使</b> 杜门 · 落巽四 ]</span>\n    <span>[ <b>空亡</b> 辰巳 ]</span>\n    <span>[ <b>旬首</b> 甲午辛 ]</span>\n    <span>[ <b>四柱</b> 丙午 / 己亥 / 辛丑 / 己亥 ]</span>\n    <span>[ <em>状态：示意展示</em> ]</span>\n    <span>[ <b>局</b> 阳遁三局 ]</span>\n    <span>[ <b>值符</b> 天辅 · 落巽四 ]</span>\n    <span>[ <b>值使</b> 杜门 · 落巽四 ]</span>\n    <span>[ <b>空亡</b> 辰巳 ]</span>\n    <span>[ <b>旬首</b> 甲午辛 ]</span>\n    <span>[ <b>四柱</b> 丙午 / 己亥 / 辛丑 / 己亥 ]</span>\n    <span>[ <em>状态：盘面已就绪</em> ]</span>\n  </div>\n</div>\n\n<!-- ===== 引擎 ===== -->\n<section class=\"sec\" id=\"engine\">\n  <div class=\"wrap\">\n    <div class=\"sec-head reveal\">\n      <div>\n        <div class=\"kicker\">ENGINE / 04 MODULES</div>\n        <h2 class=\"sec-title\">把一盘之势，<span>编译成动作</span></h2>\n      </div>\n      <p class=\"sec-note\">DISPLAY ONLY · 示例数据<br>不构成决策依据</p>\n    </div>\n    <div class=\"cards reveal\">\n      <div class=\"card\">\n        <span class=\"idx\">MOD.01 / CAST</span>\n        <h4>定局排盘</h4>\n        <p>节气 → 阴阳遁 → 局数，逐层收敛。四柱一键成盘，奇仪落宫自动对位。</p>\n        <div class=\"meter\"><span>LOAD</span><div class=\"bar\" style=\"--v:92%\"></div><span>92</span></div>\n      </div>\n      <div class=\"card\">\n        <span class=\"idx\">MOD.02 / SCAN</span>\n        <h4>宫位扫描</h4>\n        <p>神、星、门、干四层叠加，扫描旺衰与生克，定位真正的核心宫。</p>\n        <div class=\"meter\"><span>DEPTH</span><div class=\"bar\" style=\"--v:78%\"></div><span>04</span></div>\n      </div>\n      <div class=\"card\">\n        <span class=\"idx\">MOD.03 / DB</span>\n        <h4>格局库</h4>\n        <p>查阅奇门基础知识与格局资料，结合具体盘面学习。</p>\n        <div class=\"meter\"><span>INDEX</span><div class=\"bar\" style=\"--v:68%\"></div><span>68</span></div>\n      </div>\n      <div class=\"card\">\n        <span class=\"idx\">MOD.04 / LOG</span>\n        <h4>复盘日志</h4>\n        <p>判断与结果一并入库。偏差值留档，下一次的校准靠它。</p>\n        <div class=\"meter\"><span>FEED</span><div class=\"bar\" style=\"--v:86%\"></div><span>1.2K</span></div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ===== 九宫矩阵（示意，非实时排盘） ===== -->\n<section class=\"sec\" id=\"board\" style=\"padding-top:0\">\n  <div class=\"wrap\">\n    <div class=\"sec-head reveal\">\n      <div>\n        <div class=\"kicker\">MATRIX / 九宫示意 · 非实时盘面</div>\n        <h2 class=\"sec-title\">一宫四层，<span>层层见事</span></h2>\n      </div>\n      <p class=\"sec-note\">离九为值符之宫<br>景门主文书声名</p>\n    </div>\n\n    <div class=\"hud-grid\">\n      <div class=\"board reveal\" id=\"board9\">\n        <div class=\"hcell\"><div class=\"t\"><span>九天</span><b>天辅</b></div><div class=\"c\">壬<small>杜门</small></div><div class=\"b\"><span>巽四</span><span>乙</span></div></div>\n        <div class=\"hcell lit\"><div class=\"t\"><span>值符</span><b>天英</b></div><div class=\"c\">戊<small>景门</small></div><div class=\"b\"><span>离九</span><span>丙</span></div></div>\n        <div class=\"hcell\"><div class=\"t\"><span>螣蛇</span><b>天芮</b></div><div class=\"c\">癸<small>死门</small></div><div class=\"b\"><span>坤二</span><span>丁</span></div></div>\n        <div class=\"hcell\"><div class=\"t\"><span>太阴</span><b>天冲</b></div><div class=\"c\">庚<small>伤门</small></div><div class=\"b\"><span>震三</span><span>壬</span></div></div>\n        <div class=\"hcell center\"><div class=\"t\"><span></span><b>中五</b></div><div class=\"c\">中<small>寄坤二</small></div><div class=\"b\"><span>天禽</span><span>—</span></div></div>\n        <div class=\"hcell\"><div class=\"t\"><span>六合</span><b>天柱</b></div><div class=\"c\">辛<small>惊门</small></div><div class=\"b\"><span>兑七</span><span>癸</span></div></div>\n        <div class=\"hcell\"><div class=\"t\"><span>白虎</span><b>天任</b></div><div class=\"c\">丙<small>生门</small></div><div class=\"b\"><span>艮八</span><span>戊</span></div></div>\n        <div class=\"hcell\"><div class=\"t\"><span>玄武</span><b>天蓬</b></div><div class=\"c\">乙<small>休门</small></div><div class=\"b\"><span>坎一</span><span>辛</span></div></div>\n        <div class=\"hcell\"><div class=\"t\"><span>九地</span><b>天心</b></div><div class=\"c\">丁<small>开门</small></div><div class=\"b\"><span>乾六</span><span>庚</span></div></div>\n      </div>\n\n      <div class=\"terminal reveal\">\n        <div class=\"term-bar\"><span></span><span></span><span></span><em>qimen://readout/example · 示例</em></div>\n        <div class=\"term-body\">\n          <div><span class=\"p\">qimen&gt;</span> <span class=\"k\">load --time now</span></div>\n          <div><span class=\"p\">→</span> 四柱 <span class=\"m\">丙午 己亥 辛丑 己亥</span></div>\n          <div><span class=\"p\">→</span> 节气 立冬 · 阳遁 <span class=\"m\">三局</span></div>\n          <div><span class=\"p\">→</span> 值符 <span class=\"g\">天辅</span> 值使 <span class=\"g\">杜门</span></div>\n          <div><span class=\"p\">→</span> 空亡 辰巳 · 旬首 甲午辛</div>\n          <div><span class=\"p\">qimen&gt;</span> <span class=\"k\">scan core</span></div>\n          <div><span class=\"p\">→</span> 核心宫 <span class=\"g\">离九</span> · 值符临宫</div>\n          <div><span class=\"p\">→</span> 门象 景门 · 主 文书 / 声名 / 契约</div>\n          <div><span class=\"p\">→</span> 提示 火性易急，宜先立据再扩张</div>\n          <div><span class=\"p\">qimen&gt;</span> <span class=\"k\">watch --palace 离九</span></div>\n          <div><span class=\"p\">→</span> 六仪 戊 己 庚 辛 壬 癸</div>\n          <div><span class=\"p\">→</span> 三奇 乙 丙 丁 · 格局 三奇得使</div>\n          <div><span class=\"p\">→</span> 关注 文书契约的落笔时点</div>\n          <div><span class=\"p\">→</span> 应期 三日内 / 五日后</div>\n          <div><span class=\"p\">qimen&gt;</span> <span class=\"cursor\"></span></div>\n        </div>\n        <div class=\"term-foot\"><span>LAT 42ms</span><span>SESSION / QM-031</span></div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ===== 日志 ===== -->\n<section class=\"sec\" id=\"logs\" style=\"border-top:1px solid rgba(163,201,187,.16)\"><div class=\"wrap\"><div class=\"sec-head reveal\"><div><div class=\"kicker\">ARCHIVE / 案例学习</div><h2 class=\"sec-title\">从案例中，<span>学习与复盘</span></h2></div><a class=\"btn\" href=\"/cases\" target=\"_top\">查看案例</a></div></div></section>\n\n<!-- ===== CTA ===== -->\n<section class=\"cta\" id=\"cta\">\n  <div class=\"ring\"></div>\n  <div class=\"wrap cta-inner reveal\">\n    <h2>盘面已就绪，<span>等你落子</span></h2>\n    <p>NO DESTINY / ONLY TRAJECTORY<br>奇门不是宿命，是一张更清晰的地图</p>\n    <a class=\"btn hot\" href=\"/divination\" target=\"_top\">接 入 盘 面 <span>→</span></a>\n  </div>\n</section>\n\n<footer>\n  <div class=\"wrap foot\">\n    <span>玄枢 QIMEN PROTOCOL · 演示页面 / 盘面数据仅供研习</span>\n    <span class=\"ok\">ALL SYSTEMS NOMINAL</span>\n  </div>\n</footer>\n\n<script>\nconst NS='http://www.w3.org/2000/svg';\nfunction el(tag,attrs={}){const e=document.createElementNS(NS,tag);for(const k in attrs)e.setAttribute(k,attrs[k]);return e;}\nconst polar=(a,r,deg=0)=>{const rad=(a-90)*Math.PI/180;return [r*Math.cos(rad),r*Math.sin(rad)];};\n\n/* 刻度 */\nconst ticks=document.getElementById('ticks');\nfor(let d=0;d<360;d+=2){\n  const long=d%30===0?12:(d%10===0?7:3.5);\n  const [x1,y1]=polar(d,282), [x2,y2]=polar(d,282-long);\n  ticks.appendChild(el('line',{x1,y1,x2,y2,'stroke-width':d%30===0?1.4:.7,'stroke-opacity':d%30===0?.9:.45}));\n}\nconst degs=document.getElementById('degrees');\nfor(let d=0;d<360;d+=30){\n  const [x,y]=polar(d,266);\n  const t=el('text',{x,y,fill:'#4e6e62','text-anchor':'middle','dominant-baseline':'middle'});\n  t.textContent=String(d).padStart(3,'0');degs.appendChild(t);\n}\n\n/* 二十四山 */\nconst SHAN=['子','癸','丑','艮','寅','甲','卯','乙','辰','巽','巳','丙','午','丁','未','坤','申','庚','酉','辛','戌','乾','亥','壬'];\nconst shanG=document.getElementById('shan');\nSHAN.forEach((s,i)=>{\n  const a=i*15;const [x,y]=polar(a,234);\n  const t=el('text',{x,y,'text-anchor':'middle','dominant-baseline':'middle'});\n  t.textContent=s;\n  t.setAttribute('fill',['艮','巽','坤','乾'].includes(s)?'#d8bb8c':'#a8d2c6');\n  t.setAttribute('font-size',['艮','巽','坤','乾'].includes(s)?16:13);\n  shanG.appendChild(t);\n});\n\n/* 八卦 */\nconst GUA=['☵','☶','☳','☴','☲','☷','☱','☰']; // 坎艮震巽离坤兑乾（后天方位）\nconst guaG=document.getElementById('gua');\nGUA.forEach((g,i)=>{\n  const a=i*45;const [x,y]=polar(a,206);\n  const t=el('text',{x,y,'text-anchor':'middle','dominant-baseline':'middle',fill:'#c9a06a'});\n  t.textContent=g;guaG.appendChild(t);\n});\n\n/* 八门 8 方位 */\nconst DOORS=['休','生','伤','杜','景','死','惊','开'];\nconst doorsG=document.getElementById('doors');\nDOORS.forEach((d,i)=>{\n  const a=i*45, [x,y]=polar(a,172);\n  const g=el('g',{});\n  g.appendChild(el('rect',{x:x-15,y:y-11,width:30,height:22,fill:'rgba(6,16,14,.85)',stroke:'#a3c9bb','stroke-opacity':.5,'stroke-width':.8}));\n  const t=el('text',{x, y:y+5,'text-anchor':'middle','font-family':\"'Noto Serif SC',serif\",'font-size':13,fill:'#c9e4da'});\n  t.textContent=d;g.appendChild(t);doorsG.appendChild(g);\n});\n\n/* 九星 · 装饰排列 */\nconst STARS=['天蓬','天芮','天冲','天辅','天禽','天心','天柱','天任','天英'];\nconst starsG=document.getElementById('stars');\nSTARS.forEach((s,i)=>{\n  const a=i*40, [x,y]=polar(a,131);\n  const t=el('text',{x,y,'text-anchor':'middle','dominant-baseline':'middle','font-size':11});\n  t.textContent=s;starsG.appendChild(t);\n});\n\n/* 三奇六仪 */\nconst GANS=['戊','己','庚','辛','壬','癸','丁','丙','乙'];\nconst gansG=document.getElementById('gans');\nGANS.forEach((g,i)=>{\n  const a=i*40, [x,y]=polar(a,95);\n  const t=el('text',{x,y,'text-anchor':'middle','dominant-baseline':'middle',fill:i<3?'#efe0c8':'#e6eee8'});\n  t.textContent=g;gansG.appendChild(t);\n});\n\n/* 内环 rotate 标尺 */\nconst cr=document.getElementById('coreRing');\nfor(let d=0;d<360;d+=15){\n  const [x1,y1]=polar(d,74),[x2,y2]=polar(d,66);\n  cr.appendChild(el('line',{x1,y1,x2,y2,'stroke-width':.6,'stroke-opacity':.4}));\n}\n\n/* 三支动轴 */\nfunction axis(id,r,len,count,tickLen){\n  const g=document.getElementById(id);\n  for(let i=0;i<count;i++){\n    const a=i*(360/count);\n    const [x1,y1]=polar(a,r-len), [x2,y2]=polar(a,r);\n    g.appendChild(el('line',{x1,y1,x2,y2,'stroke-width':.8}));\n    const [tx,ty]=polar(a+ (360/count)/2, r-len*.4);\n    g.appendChild(el('circle',{cx:tx,cy:ty,r:1.6,fill:'currentColor','fill-opacity':.6}));\n  }\n}\naxis('ringA',205,34,12);\naxis('ringB',160,20,18);\naxis('ringC',88,12,36);\n\n/* 外环 blips */\nconst blips=document.getElementById('blips');\n[[12,268,'#c9a06a'],[78,268,'#a3c9bb'],[155,268,'#a3c9bb'],[212,270,'#8a98a0'],[298,268,'#c9a06a'],[340,270,'#a3c9bb']].forEach(([a,r,c])=>{\n  const [x,y]=polar(a,r);\n  const dot=el('circle',{cx:x,cy:y,r:2.6,fill:c,'fill-opacity':.9});\n  dot.setAttribute('style',`filter:drop-shadow(0 0 6px ${c})`);\n  blips.appendChild(dot);\n  const [lx,ly]=polar(a,r+9);\n  const l=el('line',{x1:x,y1:y,x2:lx,y2:ly,stroke:c,'stroke-opacity':.5,'stroke-width':1});\n  blips.appendChild(l);\n});\n\n/* 动画：扫掠、三环反向缓慢转 */\nconst sweep=document.getElementById('sweep');\nlet ang=0;\nfunction spin(){\n  ang=(ang+0.55)%360;\n  sweep.setAttribute('transform',`rotate(${ang})`);\n  requestAnimationFrame(spin);\n}\nspin();\nconst rA=document.getElementById('ringA'), rB=document.getElementById('ringB'), rC=document.getElementById('ringC');\nlet a1=0,a2=0,a3=0;\nfunction slow(){\n  a1=(a1+0.12)%360; a2=(a2-0.08+360)%360; a3=(a3+0.05)%360;\n  rA.setAttribute('transform',`rotate(${a1})`);\n  rB.setAttribute('transform',`rotate(${a2})`);\n  rC.setAttribute('transform',`rotate(${a3})`);\n  requestAnimationFrame(slow);\n}\nslow();\n\n/* 导航 & 出现 */\nconst hdr=document.getElementById('hdr');\nconst links=[...document.querySelectorAll('.nav-links a')];\nwindow.addEventListener('scroll',()=>{\n  hdr.classList.toggle('scrolled',window.scrollY>30);\n  let cur='top';\n  links.forEach(a=>{const id=a.getAttribute('href').slice(1);const el=document.getElementById(id);if(el&&el.getBoundingClientRect().top<=140)cur=id;});\n  links.forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+cur));\n},{passive:true});\nconst io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}}),{threshold:.1});\ndocument.querySelectorAll('.reveal').forEach(x=>io.observe(x));\n</script>\n</body>\n</html>\n"

export default function Home({ skin }) {
  if (skin === 'moon') return <LightHome />
  return <iframe key={skin} title="奇门遁甲首页" srcDoc={skin === 'jade' ? jadeHomepage : paperHomepage} style={{ display: 'block', width: '100%', height: 'calc(100dvh - 4rem)', minHeight: '500px', border: 0 }} />
}
